/// AST for the nsh shell parser

#[derive(Debug, Clone)]
pub enum Redirect {
    /// > file
    Output(String),
    /// >> file
    Append(String),
    /// < file
    Input(String),
    /// 2> file
    Stderr(String),
    /// 2>> file
    StderrAppend(String),
    /// &> file (stdout and stderr to file)
    Both(String),
    /// 2>&1
    StderrToStdout,
    /// 1>&2
    StdoutToStderr,
    /// n> file
    Fd(u32, String),
    /// n>&m
    FdDup(u32, u32),
    /// n>>&m
    FdDupAppend(u32, u32),
    /// << MARKER
    Heredoc(String, String), // (marker, content)
    /// <<< string
    Herestring(String),
    /// Process substitution <(cmd)
    ProcSubIn(Box<AndOrList>),
}

#[derive(Debug, Clone)]
pub enum WordPart {
    Literal(String),
    Variable(String),
    /// ${VAR:-default}
    VarDefault(String, Vec<WordPart>),
    /// ${VAR:=default}
    VarAssign(String, Vec<WordPart>),
    /// ${#VAR}
    VarLen(String),
    /// ${VAR/pat/repl}
    VarReplace(String, String, Vec<WordPart>, bool), // (var, pattern, replacement, global)
    /// $(cmd)
    CmdSub(Box<AndOrList>),
    /// `cmd`
    BacktickSub(Box<AndOrList>),
    /// $(( expr ))
    ArithSub(ArithExpr),
    /// Process substitution <(cmd)
    ProcSubIn(Box<AndOrList>),
    /// Glob pattern (*, ?, [...)
    Glob(String),
    /// ~ expansion
    Tilde,
    /// ~user expansion
    TildeUser(String),
}

#[derive(Debug, Clone)]
pub struct Word(pub Vec<WordPart>);

#[derive(Debug, Clone)]
pub enum ArithExpr {
    Number(i64),
    Var(String),
    BinOp(Box<ArithExpr>, ArithOp, Box<ArithExpr>),
    UnaryMinus(Box<ArithExpr>),
    PostIncrement(String),
    PostDecrement(String),
    PreIncrement(String),
}

#[derive(Debug, Clone)]
pub enum ArithOp {
    Add,
    Sub,
    Mul,
    Div,
    Mod,
    Eq,
    Ne,
    Lt,
    Le,
    Gt,
    Ge,
}

#[derive(Debug, Clone)]
pub struct SimpleCommand {
    pub env_assigns: Vec<(String, Word)>,  // VAR=val before cmd
    pub name: Option<Word>,
    pub args: Vec<Word>,
    pub redirects: Vec<Redirect>,
}

#[derive(Debug, Clone)]
pub enum CompoundCommand {
    Simple(SimpleCommand),
    Pipeline(Vec<SimpleCommand>),
    If {
        condition: Box<AndOrList>,
        then_body: Vec<Statement>,
        elif_clauses: Vec<(AndOrList, Vec<Statement>)>,
        else_body: Option<Vec<Statement>>,
    },
    While {
        condition: Box<AndOrList>,
        body: Vec<Statement>,
    },
    ForIn {
        var: String,
        items: Vec<Word>,
        body: Vec<Statement>,
    },
    ForArith {
        init: Option<ArithExpr>,
        condition: Option<ArithExpr>,
        step: Option<ArithExpr>,
        body: Vec<Statement>,
    },
    Case {
        word: Word,
        arms: Vec<(Vec<Word>, Vec<Statement>)>,
    },
    Function {
        name: String,
        body: Vec<Statement>,
    },
    Subshell(Vec<Statement>),
    Group(Vec<Statement>),
}

#[derive(Debug, Clone)]
pub enum Statement {
    Command(CompoundCommand, Vec<Redirect>),
    AndOr(AndOrList),
    Background(AndOrList),
    Assignment(Vec<(String, Word)>),
}

#[derive(Debug, Clone)]
pub struct AndOrList {
    pub first: Pipeline,
    pub rest: Vec<(AndOrOp, Pipeline)>,
}

#[derive(Debug, Clone)]
pub enum AndOrOp {
    And,
    Or,
}

#[derive(Debug, Clone)]
pub struct Pipeline {
    pub negate: bool,
    pub commands: Vec<SimpleCommand>,
}
RUST_EOF

