cat > /workspace/nsh_impl/src/main.rs << 'RUST_EOF'
mod parser;
mod shell;
mod builtins;
mod expand;
mod process;
mod pattern;

use std::env;
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::PathBuf;

fn print_version() {
    println!("0.4.2");
}

fn print_help(prog: &str) {
    println!("nsh 0.4.2");
    println!("A command-line shell that focuses on performance and productivity.");
    println!();
    println!("USAGE:");
    println!("    {} [FLAGS] [OPTIONS] [FILE]", prog);
    println!();
    println!("FLAGS:");
    println!("    -h, --help       Prints help information");
    println!("    -l, --login      Behave like a login shell");
    println!("        --norc       Don't load nshrc");
    println!("        --version    Print the version");
    println!();
    println!("OPTIONS:");
    println!("    -c <command>        The command to be executed");
    println!();
    println!("ARGS:");
    println!("    <FILE>    The file to be executed");
}

fn get_nshrc_path() -> Option<PathBuf> {
    // Check $XDG_CONFIG_HOME/nsh/nshrc first
    if let Ok(xdg) = env::var("XDG_CONFIG_HOME") {
        let p = PathBuf::from(xdg).join("nsh").join("nshrc");
        if p.exists() {
            return Some(p);
        }
    }
    // Check ~/.nshrc
    if let Ok(home) = env::var("HOME") {
        let p = PathBuf::from(home).join(".nshrc");
        if p.exists() {
            return Some(p);
        }
    }
    // Check default XDG location
    if let Ok(home) = env::var("HOME") {
        let p = PathBuf::from(home).join(".config").join("nsh").join("nshrc");
        if p.exists() {
            return Some(p);
        }
    }
    None
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let prog = args.get(0).map(|s| s.as_str()).unwrap_or("nsh");

    let mut command: Option<String> = None;
    let mut file: Option<String> = None;
    let mut login = false;
    let mut norc = false;
    let mut i = 1;

    while i < args.len() {
        match args[i].as_str() {
            "--version" => {
                print_version();
                std::process::exit(0);
            }
            "--help" | "-h" => {
                print_help(prog);
                std::process::exit(0);
            }
            "-l" | "--login" => {
                login = true;
                i += 1;
            }
            "--norc" => {
                norc = true;
                i += 1;
            }
            "-c" => {
                i += 1;
                if i >= args.len() {
                    eprintln!("{}: -c requires an argument", prog);
                    std::process::exit(1);
                }
                command = Some(args[i].clone());
                i += 1;
            }
            s if s.starts_with("-c") => {
                command = Some(s[2..].to_string());
                i += 1;
            }
            s if !s.starts_with('-') => {
                file = Some(s.to_string());
                i += 1;
                break;
            }
