/// Shell parser - implements a recursive descent parser for nsh

#[derive(Debug, Clone)]
pub struct ParseError {
    pub line: usize,
    pub col: usize,
    pub input: String,
    pub expected: Vec<&'static str>,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, " --> {}:{}\n  |\n", self.line, self.col)?;
        let lines: Vec<&str> = self.input.lines().collect();
        if self.line > 0 && self.line <= lines.len() {
            write!(f, "{} | {}\n  |", self.line, lines[self.line - 1])?;
            // Add the ^ indicator
            let spaces = " ".repeat(self.col.saturating_sub(1));
            write!(f, " {}^---\n  |", spaces)?;
        }
        if !self.expected.is_empty() {
            write!(f, "\n  = expected {}", self.expected.join(", or "))?;
        }
        Ok(())
    }
}

/// AST nodes for the shell

#[derive(Debug, Clone)]
pub enum Redirect {
    Output(Word),        // >
    Append(Word),        // >>
    Input(Word),         // <
    Stderr(Word),        // 2>
    StderrAppend(Word),  // 2>>
    StderrToStdout,      // 2>&1
    StdoutToStderr,      // 1>&2
    Both(Word),          // &>
    FdOut(u32, Word),    // n>
    FdIn(u32, Word),     // n<
    FdDup(u32, u32),     // n>&m
    FdClose(u32),        // n>&-
    Heredoc(String),     // << MARKER (content filled in after parsing)
    HereString(Word),    // <<< word (not supported but parsed)
    ProcSubIn(Box<AndOrList>), // <(cmd)
    ProcSubOut(Box<AndOrList>), // >(cmd)
}

#[derive(Debug, Clone)]
pub enum WordPart {
    Literal(String),
    Variable(String),
    VarDefault { name: String, op: VarOp, default: Vec<WordPart>, colon: bool },
    VarLen(String),
    VarReplace { name: String, pattern: String, replacement: Vec<WordPart>, global: bool },
    CmdSub(Box<AndOrList>),
    BacktickSub(Box<AndOrList>),
    ArithSub(Box<ArithExpr>),
    ProcSubIn(Box<AndOrList>),
    ProcSubOut(Box<AndOrList>),
    Tilde,
    TildeUser(String),
}

#[derive(Debug, Clone)]
pub enum VarOp {
    Default,    // :-
    Assign,     // :=
}

#[derive(Debug, Clone)]
pub struct Word {
    pub parts: Vec<WordPart>,
    pub quoted: bool,
}

impl Word {
    pub fn literal(s: &str) -> Self {
        Word { parts: vec![WordPart::Literal(s.to_string())], quoted: false }
    }
}

#[derive(Debug, Clone)]
pub enum ArithExpr {
    Number(i64),
    Var(String),
    Add(Box<ArithExpr>, Box<ArithExpr>),
    Sub(Box<ArithExpr>, Box<ArithExpr>),
    Mul(Box<ArithExpr>, Box<ArithExpr>),
    Div(Box<ArithExpr>, Box<ArithExpr>),
    Mod(Box<ArithExpr>, Box<ArithExpr>),
    Eq(Box<ArithExpr>, Box<ArithExpr>),
    Ne(Box<ArithExpr>, Box<ArithExpr>),
    Lt(Box<ArithExpr>, Box<ArithExpr>),
    Le(Box<ArithExpr>, Box<ArithExpr>),
    Gt(Box<ArithExpr>, Box<ArithExpr>),
    Ge(Box<ArithExpr>, Box<ArithExpr>),
    Neg(Box<ArithExpr>),
    PostInc(String),
    PostDec(String),
    PreInc(String),
    PreDec(String),
    Ternary(Box<ArithExpr>, Box<ArithExpr>, Box<ArithExpr>),
}

#[derive(Debug, Clone)]
pub struct SimpleCommand {
    pub env: Vec<(String, Word)>,
    pub name: Option<Word>,
    pub args: Vec<Word>,
    pub redirects: Vec<Redirect>,
    pub heredoc_contents: Vec<String>, // Filled after parsing
}

#[derive(Debug, Clone)]
pub struct Pipeline {
    pub commands: Vec<SimpleCommand>,
    pub negated: bool,
}

#[derive(Debug, Clone)]
pub struct AndOrList {
    pub first: Pipeline,
    pub rest: Vec<(bool, Pipeline)>, // (is_and, pipeline)  - true=&&, false=||
}

#[derive(Debug, Clone)]
pub enum Command {
    SimpleCmd(SimpleCommand),
    If {
        cond: Vec<AndOrList>,
        then_body: Vec<Statement>,
        elif_parts: Vec<(Vec<AndOrList>, Vec<Statement>)>,
        else_body: Option<Vec<Statement>>,
    },
    While {
        cond: Vec<AndOrList>,
        body: Vec<Statement>,
    },
    ForIn {
        var: String,
        items: Vec<Word>,
        body: Vec<Statement>,
    },
    ForArith {
        init: Option<Box<ArithExpr>>,
        cond: Option<Box<ArithExpr>>,
        step: Option<Box<ArithExpr>>,
        body: Vec<Statement>,
    },
    Case {
        word: Word,
        arms: Vec<CaseArm>,
    },
    Function {
        name: String,
        body: Vec<Statement>,
    },
    Subshell(Vec<Statement>),
    Group(Vec<Statement>),
}

#[derive(Debug, Clone)]
pub struct CaseArm {
    pub patterns: Vec<Word>,
    pub body: Vec<Statement>,
}

#[derive(Debug, Clone)]
pub struct Statement {
    pub cmd: Command,
    pub redirects: Vec<Redirect>,
    pub background: bool,
}

/// The main parser struct
pub struct Parser<'a> {
    input: &'a str,
    pos: usize,
    heredoc_queue: Vec<(String, usize)>, // (marker, target_index)
}

impl<'a> Parser<'a> {
    pub fn new(input: &'a str) -> Self {
        Parser { input, pos: 0, heredoc_queue: Vec::new() }
    }

    fn remaining(&self) -> &str {
        &self.input[self.pos..]
    }

    fn peek(&self) -> Option<char> {
        self.remaining().chars().next()
    }

    fn peek2(&self) -> Option<char> {
        let mut chars = self.remaining().chars();
        chars.next();
        chars.next()
    }

    fn advance(&mut self) -> Option<char> {
        let c = self.remaining().chars().next()?;
        self.pos += c.len_utf8();
        Some(c)
    }

    fn expect_char(&mut self, c: char) -> Result<(), ParseError> {
        if self.peek() == Some(c) {
            self.advance();
            Ok(())
        } else {
            Err(self.error(vec!["expected char"]))
        }
    }

    fn consume_if(&mut self, s: &str) -> bool {
        if self.remaining().starts_with(s) {
            self.pos += s.len();
            true
        } else {
            false
        }
    }

    fn line_col(&self) -> (usize, usize) {
        let before = &self.input[..self.pos];
        let line = before.chars().filter(|&c| c == '\n').count() + 1;
        let col = before.rfind('\n').map(|p| self.pos - p).unwrap_or(self.pos + 1);
        (line, col)
    }

    fn error(&self, expected: Vec<&'static str>) -> ParseError {
        let (line, col) = self.line_col();
        ParseError {
            line,
            col,
            input: self.input.to_string(),
            expected,
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' {
                self.advance();
            } else if c == '\\' && self.peek2() == Some('\n') {
                self.advance(); // backslash
                self.advance(); // newline
            } else {
                break;
            }
        }
    }

    fn skip_whitespace_and_newlines(&mut self) {
        loop {
            while let Some(c) = self.peek() {
                if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                    self.advance();
                } else if c == '\\' && self.peek2() == Some('\n') {
                    self.advance();
                    self.advance();
                } else {
                    break;
                }
            }
            // Skip comments
            if self.peek() == Some('#') {
                while let Some(c) = self.peek() {
                    if c == '\n' { break; }
                    self.advance();
                }
            } else {
                break;
            }
        }
    }

    fn skip_comment_and_newline(&mut self) {
        if self.peek() == Some('#') {
            while let Some(c) = self.peek() {
                if c == '\n' { break; }
                self.advance();
            }
        }
    }

    fn at_word_end(&self) -> bool {
        match self.peek() {
            None => true,
            Some(c) => matches!(c, ' ' | '\t' | '\n' | '\r' | ';' | '|' | '&' | '(' | ')' | '<' | '>'),
        }
    }

    /// Parse the complete input as a list of statements
    pub fn parse_program(&mut self) -> Result<Vec<Statement>, ParseError> {
        let stmts = self.parse_statement_list()?;
        self.skip_whitespace_and_newlines();
        if self.pos < self.input.len() {
            return Err(self.error(vec!["EOI", "normal_newline", "command", "compound_list_sep"]));
        }
