/// nsh shell parser

#[derive(Debug, Clone)]
pub struct ParseError {
    pub line: usize,
    pub col: usize,
    pub input: String,
    pub expected: Vec<String>,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, " --> {}:{}\n  |", self.line, self.col)?;
        let lines: Vec<&str> = self.input.lines().collect();
        if self.line > 0 && self.line <= lines.len() {
            write!(f, "\n{} | {}\n  |", self.line, lines[self.line - 1])?;
            let spaces: String = " ".repeat(self.col.saturating_sub(1));
            write!(f, " {}^---\n  |", spaces)?;
        }
        if !self.expected.is_empty() {
            let exp = self.expected.join(", or ");
            write!(f, "\n  = expected {}", exp)?;
        }
        Ok(())
    }
}

/// Word parts for shell words
#[derive(Debug, Clone)]
pub enum WordPart {
    Literal(String),
    Variable(String),
    /// ${VAR:-word}
    VarDefault { name: String, assign: bool, word: Vec<WordPart> },
    /// ${#VAR}
    VarLen(String),
    /// ${VAR/pat/repl} or ${VAR//pat/repl}
    VarReplace { name: String, pat: String, repl: Vec<WordPart>, global: bool },
    /// $(cmd) or `cmd`
    CmdSub(Box<CommandList>),
    /// $(( arith ))
    ArithSub(ArithExpr),
    /// <( cmd )
    ProcSub(Box<CommandList>),
}

#[derive(Debug, Clone)]
pub struct Word {
    pub parts: Vec<WordPart>,
}

impl Word {
    pub fn is_empty(&self) -> bool {
        self.parts.is_empty() || self.parts.iter().all(|p| match p {
            WordPart::Literal(s) => s.is_empty(),
            _ => false,
        })
    }

    pub fn as_literal(&self) -> Option<&str> {
        if self.parts.len() == 1 {
            if let WordPart::Literal(s) = &self.parts[0] {
                return Some(s.as_str());
            }
        }
        None
    }
}

/// Arithmetic expressions
#[derive(Debug, Clone)]
pub enum ArithExpr {
    Num(i64),
    Var(String),
    Add(Box<ArithExpr>, Box<ArithExpr>),
    Sub(Box<ArithExpr>, Box<ArithExpr>),
    Mul(Box<ArithExpr>, Box<ArithExpr>),
    Div(Box<ArithExpr>, Box<ArithExpr>),
    Mod(Box<ArithExpr>, Box<ArithExpr>),
    Eq(Box<ArithExpr>, Box<ArithExpr>),
    Ne(Box<ArithExpr>, Box<ArithExpr>),
    Lt(Box<ArithExpr>, Box<ArithExpr>),
    Le(Box<ArithExpr>, Box<ArithExpr>),
    Gt(Box<ArithExpr>, Box<ArithExpr>),
    Ge(Box<ArithExpr>, Box<ArithExpr>),
    Neg(Box<ArithExpr>),
    PostInc(String),
    PostDec(String),
}

/// Redirections
#[derive(Debug, Clone)]
pub enum Redirect {
    Out(Word),            // >file
    Append(Word),         // >>file
    In(Word),             // <file
    InOut(Word),          // <>file
    StderrOut(Word),      // 2>file
    StderrAppend(Word),   // 2>>file
    StderrToStdout,       // 2>&1
    StdoutToStderr,       // 1>&2
    BothOut(Word),        // &>file
    FdOut(u32, Word),     // n>file
    FdIn(u32, Word),      // n<file  
    FdDup(u32, u32),      // n>&m
    Heredoc { marker: String, contents: String, interpolate: bool },
    ProcSubIn(Box<CommandList>),  // <(cmd)
}

/// Simple command
#[derive(Debug, Clone)]
pub struct SimpleCmd {
    pub assigns: Vec<(String, Word)>,
    pub name: Option<Word>,
    pub args: Vec<Word>,
    pub redirects: Vec<Redirect>,
}

/// A pipeline: cmd1 | cmd2 | ...
#[derive(Debug, Clone)]
pub struct Pipeline {
    pub cmds: Vec<SimpleCmd>,
}

/// An and-or list: pipeline && pipeline || pipeline
#[derive(Debug, Clone)]
pub struct AndOrList {
    pub first: Pipeline,
    pub rest: Vec<(bool, Pipeline)>,  // true=&&, false=||
}

/// A list of and-or lists (terminated by ; or &)
#[derive(Debug, Clone)]
pub struct CommandList {
    pub items: Vec<(AndOrList, bool)>,  // (list, is_background)
}

/// Compound commands
#[derive(Debug, Clone)]
pub enum Compound {
    If {
        condition: CommandList,
        then_body: CommandList,
        elif_clauses: Vec<(CommandList, CommandList)>,
        else_body: Option<CommandList>,
    },
    While {
        condition: CommandList,
        body: CommandList,
    },
    ForIn {
        var: String,
        items: Vec<Word>,
        body: CommandList,
    },
    ForArith {
        init: Option<ArithExpr>,
        cond: Option<ArithExpr>,
        step: Option<ArithExpr>,
        body: CommandList,
    },
    Case {
        word: Word,
        arms: Vec<(Vec<Word>, CommandList)>,
    },
    Subshell(CommandList),
    Group(CommandList),
    Function { name: String, body: CommandList },
    Cond { cmds: Vec<CondExpr> },  // [[ ]]
}

#[derive(Debug, Clone)]
pub enum CondExpr {
    Str(Word),
    BinStr(Word, CondBinOp, Word),
    BinNum(Word, CondNumOp, Word),
    Not(Box<CondExpr>),
    And(Box<CondExpr>, Box<CondExpr>),
    Or(Box<CondExpr>, Box<CondExpr>),
    FileTest(String, Word),  // -f, -d, etc.
    StrTest(String, Word),   // -z, -n
}

#[derive(Debug, Clone)]
pub enum CondBinOp { Eq, Ne, Lt, Le, Gt, Ge }
#[derive(Debug, Clone)]
pub enum CondNumOp { Eq, Ne, Lt, Le, Gt, Ge }

/// Top-level "statement" in our AST - can be simple or compound
#[derive(Debug, Clone)]
pub enum Stmt {
    AndOr(AndOrList),
    Compound(Compound, Vec<Redirect>),
}

pub struct Parser {
    chars: Vec<char>,
    pos: usize,
    input: String,
    // heredocs to be filled
    pending_heredocs: Vec<(String, bool)>, // (marker, interpolate)
    heredoc_contents: Vec<String>,
}

impl Parser {
    pub fn new(input: &str) -> Self {
        Parser {
            chars: input.chars().collect(),
            pos: 0,
            input: input.to_string(),
            pending_heredocs: Vec::new(),
            heredoc_contents: Vec::new(),
        }
    }

    fn remaining_str(&self) -> String {
        self.chars[self.pos..].iter().collect()
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).copied()
    }

    fn advance(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied()?;
        self.pos += 1;
        Some(c)
    }

    fn consume_if_char(&mut self, c: char) -> bool {
        if self.peek() == Some(c) {
            self.advance();
            true
        } else {
            false
        }
    }

    fn consume_str(&mut self, s: &str) -> bool {
        let chars: Vec<char> = s.chars().collect();
        if self.chars[self.pos..].starts_with(&chars) {
            self.pos += chars.len();
            true
        } else {
            false
        }
    }

    fn line_col(&self) -> (usize, usize) {
        let mut line = 1;
        let mut col = 1;
        for i in 0..self.pos.min(self.chars.len()) {
            if self.chars[i] == '\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        (line, col)
    }

    fn error(&self, expected: &[&str]) -> ParseError {
        let (line, col) = self.line_col();
        ParseError {
            line,
            col,
            input: self.input.clone(),
            expected: expected.iter().map(|s| s.to_string()).collect(),
        }
    }

    // Skip spaces and tabs (not newlines)
    fn skip_spaces(&mut self) {
        loop {
            match self.peek() {
                Some(' ') | Some('\t') => { self.advance(); }
                Some('\\') if self.peek_at(1) == Some('\n') => {
                    self.advance(); self.advance();
                }
                _ => break,
            }
        }
    }

    // Skip spaces, tabs, and newlines (and comments)
    fn skip_whitespace(&mut self) {
        loop {
            match self.peek() {
                Some(' ') | Some('\t') | Some('\n') | Some('\r') => { self.advance(); }
                Some('\\') if self.peek_at(1) == Some('\n') => {
                    self.advance(); self.advance();
                }
                Some('#') => {
                    // Skip comment
                    while let Some(c) = self.peek() {
                        if c == '\n' { break; }
                        self.advance();
                    }
                }
                _ => break,
            }
        }
    }

    fn skip_comment(&mut self) {
        if self.peek() == Some('#') {
            while let Some(c) = self.peek() {
                if c == '\n' { break; }
                self.advance();
            }
        }
    }

    fn is_word_end(&self) -> bool {
        match self.peek() {
            None => true,
            Some(c) => matches!(c, ' ' | '\t' | '\n' | '\r' | ';' | '|' | '&' | '(' | ')' | '}'),
        }
    }

    fn is_keyword(&self, kw: &str) -> bool {
        let kw_chars: Vec<char> = kw.chars().collect();
        if !self.chars[self.pos..].starts_with(&kw_chars) {
            return false;
        }
        let after_pos = self.pos + kw_chars.len();
        match self.chars.get(after_pos) {
            None => true,
            Some(&c) => matches!(c, ' ' | '\t' | '\n' | '\r' | ';' | ')' | '}' | '('),
        }
    }

    fn skip_keyword(&mut self, kw: &str) {
        self.pos += kw.chars().count();
    }

    /// Parse the top-level program
    pub fn parse_program(&mut self) -> Result<CommandList, ParseError> {
        let list = self.parse_command_list()?;
        self.skip_whitespace();
        if self.pos < self.chars.len() {
            return Err(self.error(&["EOI", "normal_newline", "command", "compound_list_sep"]));
        }
        Ok(list)
    }

    fn parse_command_list(&mut self) -> Result<CommandList, ParseError> {
        let mut items = Vec::new();
        loop {
            self.skip_whitespace();
            if self.pos >= self.chars.len() {
                break;
            }
            // Check for terminators
            if self.is_keyword("fi") || self.is_keyword("done") || self.is_keyword("esac")
                || self.is_keyword("else") || self.is_keyword("elif")
                || self.peek() == Some(')') || self.peek() == Some('}') {
                break;
            }

            match self.parse_and_or_list() {
                Ok(list) => {
                    self.skip_spaces();
                    self.skip_comment();
                    let background = if self.peek() == Some('&') && self.peek_at(1) != Some('&') {
                        self.advance();
                        true
                    } else {
                        false
                    };
                    items.push((list, background));
                    // Consume separator
                    self.skip_spaces();
                    self.skip_comment();
                    while matches!(self.peek(), Some(';') | Some('\n') | Some('\r')) {
                        self.advance();
                        self.skip_spaces();
                        self.skip_comment();
                    }
                }
                Err(e) => {
                    if items.is_empty() && self.pos < self.chars.len() {
                        return Err(e);
                    }
                    // If we have items and now fail, we're done
                    break;
                }
            }
        }
        Ok(CommandList { items })
    }

    fn parse_and_or_list(&mut self) -> Result<AndOrList, ParseError> {
        let first = self.parse_pipeline()?;
        let mut rest = Vec::new();

        loop {
            self.skip_spaces();
            let is_and = if self.consume_str("&&") {
                true
            } else if self.consume_str("||") {
                false
            } else {
                break;
            };
            self.skip_whitespace(); // Skip newlines after && or ||
            let p = self.parse_pipeline()?;
            rest.push((is_and, p));
        }

        Ok(AndOrList { first, rest })
    }

    fn parse_pipeline(&mut self) -> Result<Pipeline, ParseError> {
        let cmd = self.parse_single_command()?;
        let mut cmds = vec![cmd];

        loop {
            self.skip_spaces();
            // | but not || 
            if self.peek() == Some('|') && self.peek_at(1) != Some('|') && self.peek_at(1) != Some('&') {
                self.advance(); // consume |
                self.skip_whitespace(); // skip newlines
                let cmd = self.parse_single_command()?;
                cmds.push(cmd);
            } else {
                break;
            }
        }

        Ok(Pipeline { cmds })
    }

    /// Parse a single command (simple or compound)
    fn parse_single_command(&mut self) -> Result<SimpleCmd, ParseError> {
        self.skip_spaces();

        // Check for compound commands
        if self.is_keyword("if") {
            return self.parse_if_as_simple();
        }
        if self.is_keyword("while") {
            return self.parse_while_as_simple();
        }
        if self.is_keyword("for") {
            return self.parse_for_as_simple();
        }
        if self.is_keyword("case") {
            return self.parse_case_as_simple();
        }
        if self.is_keyword("function") {
            return self.parse_function_as_simple();
        }
        if self.peek() == Some('{') {
            return self.parse_group_as_simple();
        }
        if self.peek() == Some('(') {
            return self.parse_subshell_as_simple();
        }
        if self.consume_str("[[") {
            return self.parse_double_bracket();
        }

        self.parse_simple_command()
    }

    fn parse_simple_command(&mut self) -> Result<SimpleCmd, ParseError> {
        let mut assigns = Vec::new();
        let mut name: Option<Word> = None;
        let mut args = Vec::new();
        let mut redirects = Vec::new();

        loop {
            self.skip_spaces();

            // Check for redirects
            if let Some(r) = self.try_parse_redirect()? {
                redirects.push(r);
                continue;
            }

            if self.is_word_end() {
                break;
            }

            // Try to parse assignment (only before name)
            if name.is_none() {
                if let Some((k, v)) = self.try_parse_assignment()? {
                    assigns.push((k, v));
                    continue;
                }
            }

            // Parse a word
            let word = self.parse_word(false)?;
            if word.is_empty() {
                break;
            }

            if name.is_none() {
                name = Some(word);
            } else {
                args.push(word);
            }
        }

        // If we only have assigns and no command, that's still valid
        Ok(SimpleCmd { assigns, name, args, redirects })
    }

    fn try_parse_redirect(&mut self) -> Result<Option<Redirect>, ParseError> {
        let saved = self.pos;

        // Check for 2>&1 and similar
        if self.peek() == Some('2') && self.peek_at(1) == Some('>') && self.peek_at(2) == Some('&') && self.peek_at(3) == Some('1') {
            self.pos += 4;
            return Ok(Some(Redirect::StderrToStdout));
        }

        // 1>&2
        if self.peek() == Some('1') && self.peek_at(1) == Some('>') && self.peek_at(2) == Some('&') && self.peek_at(3) == Some('2') {
            self.pos += 4;
            return Ok(Some(Redirect::StdoutToStderr));
        }

        // &> (both to file)
        if self.peek() == Some('&') && self.peek_at(1) == Some('>') {
            self.pos += 2;
            self.skip_spaces();
            let word = self.parse_word(false)?;
            return Ok(Some(Redirect::BothOut(word)));
        }

        // 2> or 2>>
        if self.peek() == Some('2') && self.peek_at(1) == Some('>') {
            self.pos += 2;
            if self.peek() == Some('>') {
                self.advance();
                self.skip_spaces();
                let word = self.parse_word(false)?;
                return Ok(Some(Redirect::StderrAppend(word)));
            }
            // Check for 2>&-
            if self.peek() == Some('&') {
                self.advance();
                // Check for digit
                if let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        let fd = c as u32 - '0' as u32;
                        self.advance();
                        return Ok(Some(Redirect::FdDup(2, fd)));
                    }
                }
                // 2>&- (close fd)
                // We'll just ignore it
                return Ok(Some(Redirect::FdDup(2, 999))); // Hack
            }
            self.skip_spaces();
            let word = self.parse_word(false)?;
            return Ok(Some(Redirect::StderrOut(word)));
        }

        // n> file, n< file, n>> file (n is a single digit)
        if let Some(c) = self.peek() {
            if c.is_ascii_digit() && matches!(self.peek_at(1), Some('>') | Some('<')) {
                let fd = c as u32 - '0' as u32;
                self.advance(); // consume digit
                let dir = self.advance().unwrap(); // > or <
                if dir == '>' {
                    if self.peek() == Some('>') {
                        self.advance();
                        self.skip_spaces();
                        let word = self.parse_word(false)?;
                        return Ok(Some(Redirect::FdOut(fd, word))); // n>>
                    }
                    if self.peek() == Some('&') {
                        self.advance();
                        // n>&m or n>&-
                        if let Some(dc) = self.peek() {
                            if dc.is_ascii_digit() {
                                let target = dc as u32 - '0' as u32;
                                self.advance();
                                return Ok(Some(Redirect::FdDup(fd, target)));
                            }
                            if dc == '-' {
                                self.advance();
                                // close fd - we handle this by not duplicating
                                return Ok(Some(Redirect::FdDup(fd, 999))); // Hack: 999 means close
                            }
                        }
                    }
                    self.skip_spaces();
                    let word = self.parse_word(false)?;
                    return Ok(Some(Redirect::FdOut(fd, word)));
                } else {
                    // fd < file
                    self.skip_spaces();
                    let word = self.parse_word(false)?;
                    return Ok(Some(Redirect::FdIn(fd, word)));
                }
            }
        }

        // < file
        if self.peek() == Some('<') {
            if self.peek_at(1) == Some('<') {
                // << heredoc
                self.advance(); self.advance();
                self.skip_spaces();
                let marker = self.parse_heredoc_marker()?;
                // Store for later processing
                let interpolate = !marker.starts_with('"') && !marker.starts_with('\'');
                let clean_marker = marker.trim_matches('"').trim_matches('\'').to_string();
                let contents = self.read_heredoc_contents(&clean_marker)?;
                return Ok(Some(Redirect::Heredoc { 
                    marker: clean_marker, 
                    contents,
                    interpolate,
                }));
            }
            if self.peek_at(1) == Some('(') {
                self.advance(); // <
                self.advance(); // (
                let cmds = self.parse_command_list()?;
                if self.peek() != Some(')') {
                    return Err(self.error(&["')'"]))
                }
                self.advance();
                return Ok(Some(Redirect::ProcSubIn(Box::new(cmds))));
            }
            self.advance(); // <
            self.skip_spaces();
            let word = self.parse_word(false)?;
            return Ok(Some(Redirect::In(word)));
        }

        // > file, >> file
        if self.peek() == Some('>') {
            self.advance();
            if self.peek() == Some('>') {
                self.advance();
                self.skip_spaces();
                let word = self.parse_word(false)?;
                return Ok(Some(Redirect::Append(word)));
            }
            // Check for >&2 etc.
            if self.peek() == Some('&') {
                self.advance();
                if let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        let fd = c as u32 - '0' as u32;
                        self.advance();
                        return Ok(Some(Redirect::FdDup(1, fd)));
                    }
                }
                // >&- close stdout
                self.pos = saved;
                return Ok(None);
            }
            self.skip_spaces();
            let word = self.parse_word(false)?;
            return Ok(Some(Redirect::Out(word)));
        }

        Ok(None)
    }

    fn parse_heredoc_marker(&mut self) -> Result<String, ParseError> {
        // Parse heredoc marker - alphanumeric/underscore identifiers
        let mut marker = String::new();
        if let Some(c) = self.peek() {
            if !c.is_alphanumeric() && c != '_' && c != '"' && c != '\'' {
                return Err(self.error(&["heredoc_marker"]));
            }
        } else {
            return Err(self.error(&["heredoc_marker"]));
        }

        // Check for quoted marker
        if self.peek() == Some('"') || self.peek() == Some('\'') {
            let q = self.advance().unwrap();
            while let Some(c) = self.peek() {
                if c == q { self.advance(); break; }
                marker.push(c);
                self.advance();
            }
            return Ok(marker);
        }

        while let Some(c) = self.peek() {
            if c.is_alphanumeric() || c == '_' || c == '-' {
                marker.push(c);
                self.advance();
            } else {
                break;
            }
        }

        if marker.is_empty() {
            return Err(self.error(&["heredoc_marker"]));
        }

        Ok(marker)
    }

    fn read_heredoc_contents(&mut self, marker: &str) -> Result<String, ParseError> {
        // Skip to end of line first
        while let Some(c) = self.peek() {
            if c == '\n' { self.advance(); break; }
            if c == ';' || c == ')' || c == '|' || c == '&' { break; }
            self.advance();
        }

        let mut contents = String::new();
        loop {
            let mut line = String::new();
            let line_start = self.pos;
            loop {
                match self.peek() {
                    None => {
                        // EOF before heredoc end
                        contents.push_str(&line);
                        return Ok(contents);
                    }
                    Some('\n') => {
                        self.advance();
                        break;
                    }
                    Some(c) => {
                        line.push(c);
                        self.advance();
                    }
                }
            }
            if line.trim_end_matches('\r') == marker {
                break;
            }
            contents.push_str(&line);
            contents.push('\n');
            let _ = line_start;
        }
        Ok(contents)
    }

    fn try_parse_assignment(&mut self) -> Result<Option<(String, Word)>, ParseError> {
        // Look for identifier=value
        let saved = self.pos;
        let mut key = String::new();

        while let Some(c) = self.peek() {
            if c.is_alphanumeric() || c == '_' {
                key.push(c);
                self.advance();
            } else {
                break;
            }
        }

        if key.is_empty() || !self.consume_if_char('=') {
            self.pos = saved;
            return Ok(None);
        }

        // Check it starts with a letter or underscore (not just digits)
        if key.starts_with(|c: char| c.is_ascii_digit()) {
            self.pos = saved;
            return Ok(None);
        }

        let word = self.parse_word(false)?;
        Ok(Some((key, word)))
    }

    fn parse_word(&mut self, in_double_quote: bool) -> Result<Word, ParseError> {
        let mut parts = Vec::new();
        let mut literal = String::new();

        loop {
            match self.peek() {
                None => break,
                Some(c) if !in_double_quote && matches!(c, ' ' | '\t' | '\n' | '\r' | ';' | '|' | '&' | ')') => break,
                Some('}') if !in_double_quote => break,
                Some('`') => {
                    if !literal.is_empty() {
                        parts.push(WordPart::Literal(literal.clone()));
                        literal.clear();
                    }
                    self.advance(); // consume `
                    // Find matching `
                    let mut sub_input = String::new();
                    let mut depth = 0;
                    loop {
                        match self.peek() {
                            None => break,
                            Some('`') if depth == 0 => { self.advance(); break; }
                            Some('\\') => {
                                let c = self.advance().unwrap();
                                sub_input.push(c);
                                if let Some(c2) = self.advance() {
                                    sub_input.push(c2);
                                }
                            }
                            Some(_) => {
                                let c = self.advance().unwrap();
                                sub_input.push(c);
                            }
                        }
                        let _ = depth;
                    }
                    let mut sub_parser = Parser::new(&sub_input);
                    match sub_parser.parse_program() {
                        Ok(list) => parts.push(WordPart::CmdSub(Box::new(list))),
                        Err(_) => parts.push(WordPart::Literal(format!("`{}`", sub_input))),
                    }
                }
                Some('"') if !in_double_quote => {
                    if !literal.is_empty() {
                        parts.push(WordPart::Literal(literal.clone()));
                        literal.clear();
                    }
                    self.advance(); // consume opening "
                    let inner = self.parse_word(true)?;
                    for p in inner.parts { parts.push(p); }
                    if self.peek() == Some('"') {
                        self.advance(); // consume closing "
                    }
                }
                Some('"') if in_double_quote => break,
                Some('\'') if !in_double_quote => {
                    if !literal.is_empty() {
                        parts.push(WordPart::Literal(literal.clone()));
                        literal.clear();
                    }
                    self.advance(); // consume opening '
                    let mut sq_literal = String::new();
                    loop {
                        match self.peek() {
                            None | Some('\'') => { self.advance(); break; }
                            Some(c) => { sq_literal.push(c); self.advance(); }
                        }
                    }
                    if !sq_literal.is_empty() {
                        parts.push(WordPart::Literal(sq_literal));
                    }
                }
                Some('$') => {
                    if !literal.is_empty() {
                        parts.push(WordPart::Literal(literal.clone()));
                        literal.clear();
                    }
                    let part = self.parse_dollar_expansion()?;
                    if let Some(p) = part {
                        parts.push(p);
                    }
                }
                Some('<') if !in_double_quote && self.peek_at(1) == Some('(') => {
                    if !literal.is_empty() {
                        parts.push(WordPart::Literal(literal.clone()));
                        literal.clear();
                    }
                    self.advance(); // <
                    self.advance(); // (
                    let list = self.parse_command_list()?;
                    if self.peek() == Some(')') { self.advance(); }
                    parts.push(WordPart::ProcSub(Box::new(list)));
                }
                Some('~') if !in_double_quote && parts.is_empty() && literal.is_empty() => {
                    self.advance();
                    // Check if it's ~user or just ~
                    let mut user = String::new();
                    while let Some(c) = self.peek() {
                        if c == '/' || c == ' ' || c == ':' || c == '\t' || c == '\n' || c == '"' || c == '\'' {
                            break;
                        }
                        user.push(c);
                        self.advance();
                    }
                    if user.is_empty() {
                        parts.push(WordPart::Variable("HOME".to_string()));
                    } else {
                        // ~user - we'll handle this as a special literal
                        literal.push('~');
                        literal.push_str(&user);
                        // Note: We'll expand tilde-user differently
                    }
                }
                Some('\\') => {
                    self.advance(); // consume backslash
                    match self.peek() {
                        None => literal.push('\\'),
                        Some('\n') => { self.advance(); } // line continuation
                        Some(c) => {
                            if in_double_quote {
                                // In double quotes, only certain chars are escaped
                                match c {
                                    '$' | '"' | '\\' | '`' => {
                                        self.advance();
                                        literal.push(c);
                                    }
                                    _ => {
                                        literal.push('\\');
                                        // don't advance - c will be consumed next iteration
                                    }
                                }
                            } else {
                                self.advance();
                                literal.push(c);
                            }
                        }
                    }
                }
                Some('*') | Some('?') | Some('[') if !in_double_quote => {
                    literal.push(self.advance().unwrap());
                    // Will be treated as glob during expansion
                }
                Some(c) => {
                    if in_double_quote && c == ')' {
                        // Don't break on ) in double quotes
                    }
                    literal.push(c);
                    self.advance();
                }
            }
        }

        if !literal.is_empty() {
            parts.push(WordPart::Literal(literal));
        }

        Ok(Word { parts })
    }

    fn parse_dollar_expansion(&mut self) -> Result<Option<WordPart>, ParseError> {
        // We're positioned after $
        self.advance(); // consume $

        match self.peek() {
            Some('(') => {
                if self.peek_at(1) == Some('(') {
                    // $(( arith ))
                    self.advance(); // (
                    self.advance(); // (
                    let expr = self.parse_arith_expr()?;
                    self.skip_spaces();
                    if !self.consume_str("))") {
                        if !self.consume_str(")") { }
                    }
                    return Ok(Some(WordPart::ArithSub(expr)));
                } else {
                    // $( cmd )
                    self.advance(); // (
                    let list = self.parse_command_list()?;
                    if self.peek() == Some(')') { self.advance(); }
                    return Ok(Some(WordPart::CmdSub(Box::new(list))));
                }
            }
            Some('{') => {
                self.advance(); // {
                return Ok(Some(self.parse_param_expansion()?));
            }
            Some(c) if c.is_alphanumeric() || c == '_' => {
                let mut name = String::new();
                while let Some(c) = self.peek() {
                    if c.is_alphanumeric() || c == '_' {
                        name.push(c);
                        self.advance();
                    } else {
                        break;
                    }
                }
                return Ok(Some(WordPart::Variable(name)));
            }
            Some(c) if matches!(c, '?' | '$' | '!' | '#' | '@' | '*' | '-' | '0'..='9') => {
                let var = c.to_string();
                self.advance();
                return Ok(Some(WordPart::Variable(var)));
            }
            _ => {
                // Just a literal $
                return Ok(Some(WordPart::Literal("$".to_string())));
            }
        }
    }

    fn parse_param_expansion(&mut self) -> Result<WordPart, ParseError> {
        // We're positioned after ${
        // Handle ${#VAR}
        if self.peek() == Some('#') && self.peek_at(1) != Some('}') {
            self.advance(); // #
            let mut name = String::new();
            while let Some(c) = self.peek() {
                if c == '}' { break; }
                name.push(c);
                self.advance();
            }
            if self.peek() == Some('}') { self.advance(); }
            return Ok(WordPart::VarLen(name));
        }

        // Parse variable name
        let mut name = String::new();
        while let Some(c) = self.peek() {
            if c.is_alphanumeric() || c == '_' || (name.is_empty() && matches!(c, '?' | '$' | '!' | '#' | '@' | '*' | '-' | '0'..='9')) {
                name.push(c);
                self.advance();
            } else {
                break;
            }
        }

        match self.peek() {
            Some('}') => {
                self.advance();
                Ok(WordPart::Variable(name))
            }
            Some(':') => {
                self.advance(); // :
                match self.peek() {
                    Some('-') => {
                        self.advance(); // -
                        let default = self.parse_word_until('}')?;
                        if self.peek() == Some('}') { self.advance(); }
                        Ok(WordPart::VarDefault { name, assign: false, word: default.parts })
                    }
                    Some('=') => {
                        self.advance(); // =
                        let default = self.parse_word_until('}')?;
                        if self.peek() == Some('}') { self.advance(); }
                        Ok(WordPart::VarDefault { name, assign: true, word: default.parts })
                    }
                    _ => {
                        Err(self.error(&["param_op"]))
                    }
                }
            }
            Some('/') => {
                self.advance(); // /
                let global = if self.peek() == Some('/') {
                    self.advance();
                    true
                } else {
                    false
                };
                // Parse pattern
                let mut pat = String::new();
                let mut brace_depth = 0;
                while let Some(c) = self.peek() {
                    if c == '/' && brace_depth == 0 { break; }
                    if c == '{' { brace_depth += 1; }
                    if c == '}' {
                        if brace_depth == 0 { break; }
                        brace_depth -= 1;
                    }
                    pat.push(c);
                    self.advance();
                }
                let repl = if self.peek() == Some('/') {
                    self.advance();
                    let w = self.parse_word_until('}')?;
                    w.parts
                } else {
                    vec![]
                };
                if self.peek() == Some('}') { self.advance(); }
                Ok(WordPart::VarReplace { name, pat, repl, global })
            }
            _ => {
                Err(self.error(&["param_op"]))
            }
        }
    }

    fn parse_word_until(&mut self, end: char) -> Result<Word, ParseError> {
        let mut parts = Vec::new();
        let mut literal = String::new();

        loop {
            match self.peek() {
                None | Some('}') => break,
                Some(c) if c == end => break,
                Some('$') => {
                    if !literal.is_empty() {
                        parts.push(WordPart::Literal(literal.clone()));
                        literal.clear();
                    }
                    if let Some(p) = self.parse_dollar_expansion()? {
                        parts.push(p);
                    }
                }
                Some(c) => {
                    literal.push(c);
                    self.advance();
                }
            }
        }

        if !literal.is_empty() {
            parts.push(WordPart::Literal(literal));
        }

        Ok(Word { parts })
    }

    fn parse_arith_expr(&mut self) -> Result<ArithExpr, ParseError> {
        self.parse_arith_comparison()
    }

    fn parse_arith_comparison(&mut self) -> Result<ArithExpr, ParseError> {
        let left = self.parse_arith_additive()?;
        self.skip_spaces();

        let op = if self.consume_str("==") {
            Some("==")
        } else if self.consume_str("!=") {
            Some("!=")
        } else if self.consume_str("<=") {
            Some("<=")
        } else if self.consume_str(">=") {
            Some(">=")
        } else if self.peek() == Some('<') && self.peek_at(1) != Some('<') {
            self.advance();
            Some("<")
        } else if self.peek() == Some('>') && self.peek_at(1) != Some('>') {
            self.advance();
            Some(">")
        } else {
            None
        };

        if let Some(op) = op {
            self.skip_spaces();
            let right = self.parse_arith_additive()?;
            return Ok(match op {
                "==" => ArithExpr::Eq(Box::new(left), Box::new(right)),
                "!=" => ArithExpr::Ne(Box::new(left), Box::new(right)),
                "<" => ArithExpr::Lt(Box::new(left), Box::new(right)),
                "<=" => ArithExpr::Le(Box::new(left), Box::new(right)),
                ">" => ArithExpr::Gt(Box::new(left), Box::new(right)),
                ">=" => ArithExpr::Ge(Box::new(left), Box::new(right)),
                _ => unreachable!(),
            });
        }

        Ok(left)
    }

    fn parse_arith_additive(&mut self) -> Result<ArithExpr, ParseError> {
        let mut left = self.parse_arith_multiplicative()?;

        loop {
            self.skip_spaces();
            if self.peek() == Some('+') && self.peek_at(1) != Some('+') {
                self.advance();
                self.skip_spaces();
                let right = self.parse_arith_multiplicative()?;
                left = ArithExpr::Add(Box::new(left), Box::new(right));
            } else if self.peek() == Some('-') && self.peek_at(1) != Some('-') {
                self.advance();
                self.skip_spaces();
                let right = self.parse_arith_multiplicative()?;
                left = ArithExpr::Sub(Box::new(left), Box::new(right));
            } else {
                break;
            }
        }

        Ok(left)
    }

    fn parse_arith_multiplicative(&mut self) -> Result<ArithExpr, ParseError> {
        let mut left = self.parse_arith_unary()?;

        loop {
            self.skip_spaces();
            if self.peek() == Some('*') {
                self.advance();
                self.skip_spaces();
                let right = self.parse_arith_unary()?;
                left = ArithExpr::Mul(Box::new(left), Box::new(right));
            } else if self.peek() == Some('/') {
                self.advance();
                self.skip_spaces();
                let right = self.parse_arith_unary()?;
                left = ArithExpr::Div(Box::new(left), Box::new(right));
            } else if self.peek() == Some('%') {
                // Note: % might be parsed as modulo but there's a bug in original nsh
                // Let's see...
                self.advance();
                self.skip_spaces();
                // This might be parsed differently
                let right = self.parse_arith_unary()?;
                left = ArithExpr::Mod(Box::new(left), Box::new(right));
            } else {
                break;
            }
        }

        Ok(left)
    }

    fn parse_arith_unary(&mut self) -> Result<ArithExpr, ParseError> {
        self.skip_spaces();
        if self.peek() == Some('-') {
            self.advance();
            let expr = self.parse_arith_primary()?;
            return Ok(ArithExpr::Neg(Box::new(expr)));
        }
        if self.peek() == Some('+') {
            self.advance(); // unary +, ignore
        }
        self.parse_arith_postfix()
    }

    fn parse_arith_postfix(&mut self) -> Result<ArithExpr, ParseError> {
        let expr = self.parse_arith_primary()?;
        self.skip_spaces();

        if let ArithExpr::Var(ref name) = expr {
            let name = name.clone();
            if self.consume_str("++") {
                return Ok(ArithExpr::PostInc(name));
            }
            if self.consume_str("--") {
                return Ok(ArithExpr::PostDec(name));
            }
        }

        Ok(expr)
    }

    fn parse_arith_primary(&mut self) -> Result<ArithExpr, ParseError> {
        self.skip_spaces();

        if self.peek() == Some('(') {
            self.advance();
            let expr = self.parse_arith_expr()?;
            self.skip_spaces();
            if self.peek() == Some(')') { self.advance(); }
            return Ok(expr);
        }

        // Number
        if let Some(c) = self.peek() {
            if c.is_ascii_digit() || (c == '-' && self.peek_at(1).map(|c| c.is_ascii_digit()).unwrap_or(false)) {
                let mut num_str = String::new();
                if c == '-' { num_str.push('-'); self.advance(); }
                while let Some(d) = self.peek() {
                    if d.is_ascii_digit() {
                        num_str.push(d);
                        self.advance();
                    } else {
                        break;
                    }
                }
                let n: i64 = num_str.parse().unwrap_or(0);
                return Ok(ArithExpr::Num(n));
            }
        }

        // Variable name
        if let Some(c) = self.peek() {
            if c.is_alphanumeric() || c == '_' {
                let mut name = String::new();
                while let Some(c) = self.peek() {
                    if c.is_alphanumeric() || c == '_' {
                        name.push(c);
                        self.advance();
                    } else {
                        break;
                    }
                }
                return Ok(ArithExpr::Var(name));
            }
        }

        Err(self.error(&["factor"]))
    }

    // Compound command parsers (return SimpleCmd wrapping compound commands)
    // We use a different approach: parse into AST nodes stored in extensions

    fn parse_if_as_simple(&mut self) -> Result<SimpleCmd, ParseError> {
        Err(self.error(&["if command"]))
    }
    fn parse_while_as_simple(&mut self) -> Result<SimpleCmd, ParseError> {
        Err(self.error(&["while command"]))
    }
    fn parse_for_as_simple(&mut self) -> Result<SimpleCmd, ParseError> {
        Err(self.error(&["for command"]))
    }
    fn parse_case_as_simple(&mut self) -> Result<SimpleCmd, ParseError> {
        Err(self.error(&["case command"]))
    }
    fn parse_function_as_simple(&mut self) -> Result<SimpleCmd, ParseError> {
        Err(self.error(&["function command"]))
    }
    fn parse_group_as_simple(&mut self) -> Result<SimpleCmd, ParseError> {
        Err(self.error(&["group command"]))
    }
    fn parse_subshell_as_simple(&mut self) -> Result<SimpleCmd, ParseError> {
        Err(self.error(&["subshell command"]))
    }
    fn parse_double_bracket(&mut self) -> Result<SimpleCmd, ParseError> {
        Err(self.error(&["[[ command"]))
    }
}

pub fn parse(input: &str) -> Result<CommandList, ParseError> {
    let mut p = Parser::new(input);
    p.parse_program()
}
