            "-l" | "--login" => { i += 1; }
            "--norc" => { norc = true; i += 1; }
            "-c" => {
                i += 1;
                if i < args.len() {
                    command = Some(args[i].clone());
                    i += 1;
                }
            }
            s if s.starts_with("-c") && s.len() > 2 => {
