                std::process::exit(1);
            }
        }
    }

    let mut shell = exec::Shell::new();

    if !norc {
        if let Some(rc_path) = get_nshrc_path() {
            if let Ok(content) = fs::read_to_string(&rc_path) {
                shell.run_string(&content);
            }
        }
    }

    if let Some(cmd) = command {
        let rc = shell.run_string(&cmd);
        std::process::exit(rc as i32);
    } else if let Some(path) = file {
        match fs::read_to_string(&path) {
            Ok(content) => {
                let rc = shell.run_string(&content);
                std::process::exit(rc as i32);
            }
            Err(e) => {
                eprintln!("nsh: {}: {}", path, e);
                std::process::exit(1);
            }
        }
    } else {
        shell.run_interactive();
    }
}

fn print_help(prog: &str) {
    println!("nsh 0.4.2");
    println!("A command-line shell that focuses on performance and productivity.");
    println!();
    println!("USAGE:");
    println!("    {} [FLAGS] [OPTIONS] [FILE]", prog);
    println!();
    println!("FLAGS:");
    println!("    -h, --help       Prints help information");
    println!("    -l, --login      Behave like a login shell");
    println!("        --norc       Don't load nshrc");
    println!("        --version    Print the version");
    println!();
    println!("OPTIONS:");
    println!("    -c <command>        The command to be executed");
    println!();
    println!("ARGS:");
    println!("    <FILE>    The file to be executed");
}

fn get_nshrc_path() -> Option<PathBuf> {
    if let Ok(xdg) = env::var("XDG_CONFIG_HOME") {
        let p = PathBuf::from(xdg).join("nsh").join("nshrc");
        if p.exists() { return Some(p); }
    }
    if let Ok(home) = env::var("HOME") {
        let p = PathBuf::from(&home).join(".nshrc");
        if p.exists() { return Some(p); }
        let p = PathBuf::from(&home).join(".config").join("nsh").join("nshrc");
        if p.exists() { return Some(p); }
    }
    None
}
