    DoubleBracket(CondExpr),
    Test(Vec<Word>),  // [ ... ]
}

#[derive(Debug, Clone)]
pub struct CaseArm {
    pub patterns: Vec<Word>,
    pub body: CompoundList,
}

/// Arithmetic expressions
#[derive(Debug, Clone)]
pub enum ArithExpr {
    Num(i64),
    Var(String),
    Add(Box<ArithExpr>, Box<ArithExpr>),
    Sub(Box<ArithExpr>, Box<ArithExpr>),
    Mul(Box<ArithExpr>, Box<ArithExpr>),
    Div(Box<ArithExpr>, Box<ArithExpr>),
    Mod(Box<ArithExpr>, Box<ArithExpr>),
    Eq(Box<ArithExpr>, Box<ArithExpr>),
    Ne(Box<ArithExpr>, Box<ArithExpr>),
    Lt(Box<ArithExpr>, Box<ArithExpr>),
    Le(Box<ArithExpr>, Box<ArithExpr>),
    Gt(Box<ArithExpr>, Box<ArithExpr>),
    Ge(Box<ArithExpr>, Box<ArithExpr>),
    Neg(Box<ArithExpr>),
    PostInc(String),
    PostDec(String),
    CmdSub(Box<CompoundList>),
}

/// Condition expressions for [[ ]]
#[derive(Debug, Clone)]
pub enum CondExpr {
    Word(Word),
    BinOp { left: Word, op: CondOp, right: Word },
    FileTest { flag: String, word: Word },
    Not(Box<CondExpr>),
    And(Box<CondExpr>, Box<CondExpr>),
    Or(Box<CondExpr>, Box<CondExpr>),
}

#[derive(Debug, Clone)]
pub enum CondOp {
    Eq,     // ==
    Ne,     // !=
    Lt,     // <
    Le,     // <=
    Gt,     // >
    Ge,     // >=
    NumEq,  // -eq
    NumNe,  // -ne
    NumLt,  // -lt
    NumLe,  // -le
    NumGt,  // -gt
    NumGe,  // -ge
}
