use crate::types::*;
use std::path::PathBuf;

/// Shell expansion context
pub struct Expander<'a> {
    pub vars: &'a dyn Fn(&str) -> Option<String>,
}

/// Expand a word to a string (assignment context - strips whitespace from cmd subs)
pub fn expand_to_string(word: &Word, exec: &mut crate::exec::Shell) -> String {
    let parts = expand_word_parts(&word.parts, exec);
    if word.quoted {
        parts.join("")
    } else {
        parts.join("")
    }
}

/// Expand a word to a vector of strings (split on IFS)
pub fn expand_to_words(word: &Word, exec: &mut crate::exec::Shell) -> Vec<String> {
    if word.quoted {
        // Quoted - no word splitting or glob
        let s = expand_word_quoted(&word.parts, exec);
        if s.is_empty() { return vec![]; }
        return vec![s];
    }

    // Unquoted expansion: expand, split, glob
    let s = expand_word_unquoted(&word.parts, exec);

    // Check if there are any glob patterns
    let mut result = Vec::new();
    for part in &s {
        if contains_glob(part) {
            let mut globbed = glob_expand(part);
            if globbed.is_empty() {
                result.push(part.clone()); // No matches, keep pattern
            } else {
                result.append(&mut globbed);
            }
        } else {
            if !part.is_empty() {
                result.push(part.clone());
            }
        }
    }
    result
}

fn expand_word_quoted(parts: &[WordPart], exec: &mut crate::exec::Shell) -> String {
    let mut result = String::new();
    for part in parts {
        match part {
            WordPart::Literal(s) => result.push_str(s),
            WordPart::Variable(name) => {
                if let Some(v) = exec.get_var(name) {
                    result.push_str(&v);
                }
            }
            WordPart::VarLen(name) => {
                let v = exec.get_var(name).unwrap_or_default();
                result.push_str(&v.len().to_string());
            }
            WordPart::VarDefault { name, assign, word } => {
                let val = exec.get_var(name);
                if let Some(v) = val {
                    if !v.is_empty() {
                        result.push_str(&v);
                        continue;
                    }
                }
                let default = expand_word_quoted(word, exec);
                if *assign {
                    exec.set_var(name, &default);
                }
                result.push_str(&default);
            }
            WordPart::VarReplace { name, pat, repl, global } => {
                let val = exec.get_var(name).unwrap_or_default();
                let repl_str = expand_word_quoted(repl, exec);
                let replaced = do_replace(&val, pat, &repl_str, *global);
                result.push_str(&replaced);
            }
            WordPart::CmdSub(list) => {
                let output = exec.capture_output(list);
                // In quoted context, preserve whitespace (but strip trailing newlines)
                let trimmed = output.trim_end_matches('\n');
                result.push_str(trimmed);
            }
            WordPart::ArithSub(expr) => {
                let n = exec.eval_arith(expr);
                result.push_str(&n.to_string());
            }
            WordPart::ProcSub(list) => {
                // Process substitution - create a temp file or use /dev/fd/N
                let path = exec.start_proc_sub(list);
                result.push_str(&path);
            }
        }
    }
    result
}

// Returns a vector of "chunks" where each chunk might need glob expansion
fn expand_word_unquoted(parts: &[WordPart], exec: &mut crate::exec::Shell) -> Vec<String> {
    let mut chunks = vec![String::new()];

    for part in parts {
        match part {
            WordPart::Literal(s) => {
                // Literals might have IFS chars or glob chars
                let last = chunks.last_mut().unwrap();
                last.push_str(s);
            }
            WordPart::Variable(name) => {
                let val = exec.get_var(name).unwrap_or_default();
                // Split on IFS and append as separate chunks
                let ifs = exec.get_var("IFS").unwrap_or_else(|| " \t\n".to_string());
                let split = split_on_ifs(&val, &ifs);
                if split.is_empty() {
                    // Variable is empty - mark as empty
                    // Actually if empty, we should produce nothing
                } else if split.len() == 1 {
                    let last = chunks.last_mut().unwrap();
                    last.push_str(&split[0]);
                } else {
                    let last = chunks.last_mut().unwrap();
                    last.push_str(&split[0]);
                    for s in &split[1..] {
                        chunks.push(s.clone());
                    }
                }
            }
            WordPart::VarLen(name) => {
                let v = exec.get_var(name).unwrap_or_default();
                let last = chunks.last_mut().unwrap();
                last.push_str(&v.len().to_string());
            }
            WordPart::VarDefault { name, assign, word } => {
                let val = exec.get_var(name);
                let s = if let Some(v) = val {
                    if !v.is_empty() { v } else {
                        let default_w = Word { parts: word.clone(), quoted: false };
                        let d = expand_word_quoted(word, exec);
                        if *assign { exec.set_var(name, &d); }
                        d
                    }
                } else {
                    let d = expand_word_quoted(word, exec);
                    if *assign { exec.set_var(name, &d); }
                    d
                };
                let ifs = exec.get_var("IFS").unwrap_or_else(|| " \t\n".to_string());
                let split = split_on_ifs(&s, &ifs);
                if !split.is_empty() {
                    let last = chunks.last_mut().unwrap();
                    last.push_str(&split[0]);
                    for s in &split[1..] {
                        chunks.push(s.clone());
                    }
                }
            }
            WordPart::VarReplace { name, pat, repl, global } => {
                let val = exec.get_var(name).unwrap_or_default();
                let repl_str = expand_word_quoted(repl, exec);
                let replaced = do_replace(&val, pat, &repl_str, *global);
                let last = chunks.last_mut().unwrap();
                last.push_str(&replaced);
            }
            WordPart::CmdSub(list) => {
                let output = exec.capture_output(list);
                // Strip trailing newlines, but in unquoted context also strip all whitespace
                // This is the nsh behavior: strip all whitespace from cmd substitution in assignment
                let stripped: String = output.chars().filter(|c| !c.is_whitespace()).collect();
                let last = chunks.last_mut().unwrap();
                last.push_str(&stripped);
            }
            WordPart::ArithSub(expr) => {
                let n = exec.eval_arith(expr);
                let last = chunks.last_mut().unwrap();
                last.push_str(&n.to_string());
            }
            WordPart::ProcSub(list) => {
                let path = exec.start_proc_sub(list);
                let last = chunks.last_mut().unwrap();
                last.push_str(&path);
            }
        }
    }

    chunks
}

fn expand_word_parts(parts: &[WordPart], exec: &mut crate::exec::Shell) -> Vec<String> {
    vec![expand_word_quoted(parts, exec)]
}

pub fn split_on_ifs(s: &str, ifs: &str) -> Vec<String> {
    if ifs.is_empty() {
        return vec![s.to_string()];
    }

    let mut result = Vec::new();
    let mut current = String::new();
    let mut in_word = false;

    for c in s.chars() {
        if ifs.contains(c) {
            if in_word {
                result.push(current.clone());
                current.clear();
                in_word = false;
            }
        } else {
            current.push(c);
            in_word = true;
        }
    }

    if in_word && !current.is_empty() {
        result.push(current);
    }

    result
}

pub fn contains_glob(s: &str) -> bool {
    s.contains('*') || s.contains('?') || s.contains('[')
}

pub fn glob_expand(pattern: &str) -> Vec<String> {
    use std::fs;

    // Split into directory and filename parts
    let (dir, file_pat) = if let Some(pos) = pattern.rfind('/') {
        (&pattern[..pos + 1], &pattern[pos + 1..])
    } else {
        ("", pattern)
    };

    let dir_path = if dir.is_empty() { ".".to_string() } else { dir.to_string() };

    let entries = match fs::read_dir(&dir_path) {
        Ok(e) => e,
        Err(_) => return vec![],
    };

    let mut matches = Vec::new();
    for entry in entries.flatten() {
        let name = entry.file_name().to_string_lossy().to_string();
        // Skip hidden files unless pattern starts with .
        if name.starts_with('.') && !file_pat.starts_with('.') {
            continue;
        }
        if glob_match(file_pat, &name) {
            let full = if dir.is_empty() {
                name
            } else {
                format!("{}{}", dir, name)
            };
            matches.push(full);
        }
    }

    matches.sort();
    matches
}

pub fn glob_match(pattern: &str, s: &str) -> bool {
    glob_match_chars(
        &pattern.chars().collect::<Vec<_>>(), 
        &s.chars().collect::<Vec<_>>()
    )
}

fn glob_match_chars(pattern: &[char], s: &[char]) -> bool {
    let mut pi = 0;
    let mut si = 0;
    let mut star_pi = usize::MAX;
    let mut star_si = 0;

    while si < s.len() {
        if pi < pattern.len() && (pattern[pi] == '?' || pattern[pi] == s[si]) {
            pi += 1;
            si += 1;
        } else if pi < pattern.len() && pattern[pi] == '*' {
            star_pi = pi;
            star_si = si;
            pi += 1;
        } else if pi < pattern.len() && pattern[pi] == '[' {
            // Character class
            let (matched, new_pi) = match_char_class(&pattern[pi..], s[si]);
            if matched {
                pi = pi + new_pi;
                si += 1;
            } else if star_pi != usize::MAX {
                star_si += 1;
                si = star_si;
                pi = star_pi + 1;
            } else {
                return false;
            }
        } else if star_pi != usize::MAX {
            star_si += 1;
            si = star_si;
            pi = star_pi + 1;
        } else {
            return false;
        }
    }

    while pi < pattern.len() && pattern[pi] == '*' {
        pi += 1;
    }

    pi == pattern.len()
}

fn match_char_class(pattern: &[char], c: char) -> (bool, usize) {
    // Pattern starts with [
    let mut i = 1;
    let negate = if i < pattern.len() && pattern[i] == '!' {
        i += 1;
        true
    } else { false };

    let mut matched = false;
    while i < pattern.len() && pattern[i] != ']' {
        if i + 2 < pattern.len() && pattern[i + 1] == '-' && pattern[i + 2] != ']' {
            if c >= pattern[i] && c <= pattern[i + 2] {
                matched = true;
            }
            i += 3;
        } else {
            if pattern[i] == c { matched = true; }
            i += 1;
        }
    }

    let end = if i < pattern.len() { i + 1 } else { i };
    ((matched != negate), end)
}

pub fn do_replace(s: &str, pattern: &str, replacement: &str, global: bool) -> String {
    // Simple pattern replacement (not full glob)
    if global {
        let parts: Vec<&str> = s.split(pattern).collect();
        parts.join(replacement)
    } else {
        if let Some(pos) = s.find(pattern) {
            format!("{}{}{}", &s[..pos], replacement, &s[pos + pattern.len()..])
        } else {
            s.to_string()
        }
    }
}

pub fn tilde_expand(s: &str) -> String {
    if s.starts_with('~') {
        let rest = &s[1..];
        if rest.is_empty() || rest.starts_with('/') {
            let home = std::env::var("HOME").unwrap_or_else(|_| "/root".to_string());
            return format!("{}{}", home, rest);
        } else {
            // ~user expansion
            let (user, path) = rest.split_once('/').unwrap_or((rest, ""));
            // We don't support ~user lookup for now
            eprintln!("nsh: warning: ~user is not yet supported");
            // Try to run process substitution
            let user_home = format!("/home/{}", user);
            if std::path::Path::new(&user_home).exists() {
                if path.is_empty() {
                    return user_home;
                } else {
                    return format!("{}/{}", user_home, path);
                }
            }
            return s.to_string();
        }
    }
    s.to_string()
}
