            i += 1;
            match chars[i] {
                'n' => out.push('\n'),
                't' => out.push('\t'),
                'r' => out.push('\r'),
                '\\' => out.push('\\'),
                _ => { out.push('\\'); out.push(chars[i]); }
            }
        } else if chars[i] == '%' && i + 1 < chars.len() {
