pub fn builtin_test(args: &[String]) -> i32 {
    if args.is_empty() { return 1; }
    evaluate_test(args)
}

pub fn evaluate_test(args: &[String]) -> i32 {
    if args.is_empty() { return 1; }
    if args.len() == 1 {
        return if args[0].is_empty() { 1 } else { 0 };
    }

    // Handle ! negation
    if args[0] == "!" {
        let result = evaluate_test(&args[1..]);
        return if result == 0 { 1 } else { 0 };
    }

    // Handle parentheses
    if args[0] == "(" && args.last().map(|s| s.as_str()) == Some(")") {
        return evaluate_test(&args[1..args.len()-1]);
    }

    // Handle -a and -o
    // Find lowest precedence operator
    for i in 0..args.len() {
        if args[i] == "-o" {
            let left = evaluate_test(&args[..i]);
            if left == 0 { return 0; }
            return evaluate_test(&args[i+1..]);
        }
    }
    for i in 0..args.len() {
        if args[i] == "-a" {
            let left = evaluate_test(&args[..i]);
            if left != 0 { return 1; }
            return evaluate_test(&args[i+1..]);
        }
    }

    // Unary tests
    if args.len() == 2 {
        let flag = &args[0];
        let val = &args[1];
        return match flag.as_str() {
            "-z" => if val.is_empty() { 0 } else { 1 },
            "-n" => if !val.is_empty() { 0 } else { 1 },
            "-e" => if std::path::Path::new(val).exists() { 0 } else { 1 },
            "-f" => if std::path::Path::new(val).is_file() { 0 } else { 1 },
            "-d" => if std::path::Path::new(val).is_dir() { 0 } else { 1 },
            "-r" => {
                use std::os::unix::fs::PermissionsExt;
                if let Ok(m) = std::fs::metadata(val) {
                    if m.permissions().mode() & 0o444 != 0 { 0 } else { 1 }
                } else { 1 }
            }
            "-w" => {
                use std::os::unix::fs::PermissionsExt;
                if let Ok(m) = std::fs::metadata(val) {
                    if m.permissions().mode() & 0o222 != 0 { 0 } else { 1 }
                } else { 1 }
            }
            "-x" => {
                use std::os::unix::fs::PermissionsExt;
                if let Ok(m) = std::fs::metadata(val) {
                    if m.permissions().mode() & 0o111 != 0 { 0 } else { 1 }
                } else { 1 }
            }
            "-s" => {
                if let Ok(m) = std::fs::metadata(val) {
                    if m.len() > 0 { 0 } else { 1 }
                } else { 1 }
            }
            "-L" | "-h" => {
                if std::fs::symlink_metadata(val).map(|m| m.file_type().is_symlink()).unwrap_or(false) { 0 } else { 1 }
            }
            "-b" => {
                use std::os::unix::fs::FileTypeExt;
                if std::fs::metadata(val).map(|m| m.file_type().is_block_device()).unwrap_or(false) { 0 } else { 1 }
            }
            "-c" => {
                use std::os::unix::fs::FileTypeExt;
                if std::fs::metadata(val).map(|m| m.file_type().is_char_device()).unwrap_or(false) { 0 } else { 1 }
            }
            "-p" => {
                use std::os::unix::fs::FileTypeExt;
                if std::fs::metadata(val).map(|m| m.file_type().is_fifo()).unwrap_or(false) { 0 } else { 1 }
            }
            "-t" => {
                // -t fd: is fd a terminal?
                let fd: i32 = val.parse().unwrap_or(-1);
                if unsafe { libc_isatty(fd) } { 0 } else { 1 }
            }
            _ => 1,
        };
    }

    // Binary tests
    if args.len() == 3 {
        let left = &args[0];
        let op = &args[1];
        let right = &args[2];
        return match op.as_str() {
            "=" | "==" => if left == right { 0 } else { 1 },
            "!=" => if left != right { 0 } else { 1 },
            "<" => if left < right { 0 } else { 1 },
            ">" => if left > right { 0 } else { 1 },
            "-eq" => {
                let l: i64 = left.parse().unwrap_or(0);
                let r: i64 = right.parse().unwrap_or(0);
                if l == r { 0 } else { 1 }
            }
            "-ne" => {
                let l: i64 = left.parse().unwrap_or(0);
                let r: i64 = right.parse().unwrap_or(0);
                if l != r { 0 } else { 1 }
            }
            "-lt" => {
                let l: i64 = left.parse().unwrap_or(0);
                let r: i64 = right.parse().unwrap_or(0);
                if l < r { 0 } else { 1 }
            }
            "-le" => {
                let l: i64 = left.parse().unwrap_or(0);
                let r: i64 = right.parse().unwrap_or(0);
                if l <= r { 0 } else { 1 }
            }
            "-gt" => {
                let l: i64 = left.parse().unwrap_or(0);
                let r: i64 = right.parse().unwrap_or(0);
                if l > r { 0 } else { 1 }
            }
            "-ge" => {
                let l: i64 = left.parse().unwrap_or(0);
                let r: i64 = right.parse().unwrap_or(0);
                if l >= r { 0 } else { 1 }
            }
            "-ef" => {
                // Same file?
                use std::os::unix::fs::MetadataExt;
                let lm = std::fs::metadata(left.as_str());
                let rm = std::fs::metadata(right.as_str());
                if let (Ok(l), Ok(r)) = (lm, rm) {
                    if l.ino() == r.ino() && l.dev() == r.dev() { 0 } else { 1 }
                } else { 1 }
            }
            "-nt" => {
                let lm = std::fs::metadata(left.as_str()).ok();
                let rm = std::fs::metadata(right.as_str()).ok();
                if let (Some(l), Some(r)) = (lm, rm) {
                    if l.modified().ok() > r.modified().ok() { 0 } else { 1 }
                } else { 1 }
            }
            "-ot" => {
                let lm = std::fs::metadata(left.as_str()).ok();
                let rm = std::fs::metadata(right.as_str()).ok();
                if let (Some(l), Some(r)) = (lm, rm) {
                    if l.modified().ok() < r.modified().ok() { 0 } else { 1 }
                } else { 1 }
            }
            _ => 1,
        };
    }

    1
}

fn libc_isatty(fd: i32) -> bool {
    // Use libc isatty via raw syscall
    extern "C" { fn isatty(fd: i32) -> i32; }
    unsafe { isatty(fd) == 1 }
}

