    pub pid: u32,
    pub set_e: bool,  // exit on error
    pub set_u: bool,  // undefined variable is error
    pub set_n: bool,  // no-execute
    pub last_bg_pid: Option<u32>,
    pub jobs: Vec<(u32, String)>,
    pub proc_sub_fds: Vec<RawFd>,
}

impl Shell {
    pub fn new() -> Self {
        let mut vars = HashMap::new();
        // Copy environment
        for (k, v) in std::env::vars() {
            vars.insert(k, v);
        }
        // Set default IFS
        if !vars.contains_key("IFS") {
            vars.insert("IFS".to_string(), " \t\n".to_string());
        }

        Shell {
            frames: Vec::new(),
            global_vars: vars,
            exported_vars: std::env::vars().map(|(k, _)| k).collect(),
            aliases: HashMap::new(),
            functions: HashMap::new(),
            last_exit: 0,
            pid: std::process::id(),
            set_e: false,
            set_u: false,
            set_n: false,
            last_bg_pid: None,
            jobs: Vec::new(),
            proc_sub_fds: Vec::new(),
        }
    }

    pub fn get_var(&self, name: &str) -> Option<String> {
        // Special variables
        match name {
            "?" => return Some(self.last_exit.to_string()),
            "$" => return Some(self.pid.to_string()),
            "!" => return Some(self.last_bg_pid.map(|p| p.to_string()).unwrap_or_default()),
            "#" => return Some("0".to_string()),
            "0" => return Some("nsh".to_string()),
            "@" | "*" => return Some(String::new()),
            _ => {}
        }

        // Check function frame first
        for frame in self.frames.iter().rev() {
            if let Some(v) = frame.vars.get(name) {
                return Some(v.clone());
            }
        }

        self.global_vars.get(name).cloned()
    }

    pub fn set_var(&mut self, name: &str, value: &str) {
        // Check if it's a local var in current frame
        if let Some(frame) = self.frames.last_mut() {
            if frame.local_vars.contains(name) {
                frame.vars.insert(name.to_string(), value.to_string());
                return;
            }
        }
        self.global_vars.insert(name.to_string(), value.to_string());
    }

    pub fn declare_local(&mut self, name: &str, value: Option<&str>) {
        if let Some(frame) = self.frames.last_mut() {
            frame.local_vars.insert(name.to_string());
            let v = value.unwrap_or("");
            frame.vars.insert(name.to_string(), v.to_string());
        } else {
            self.global_vars.insert(name.to_string(), value.unwrap_or("").to_string());
        }
    }

    pub fn unset_var(&mut self, name: &str) {
        if let Some(frame) = self.frames.last_mut() {
            if frame.local_vars.contains(name) {
                frame.vars.remove(name);
                return;
            }
        }
        self.global_vars.remove(name);
    }

    pub fn run_string(&mut self, input: &str) -> i32 {
        match parser::parse(input) {
            Ok(list) => {
                match self.exec_compound_list(&list) {
                    Ok(rc) => rc,
                    Err(ShellError::Exit(rc)) => {
                        // This is actually handled above
                        rc
                    }
                    Err(e) => {
                        eprintln!("nsh: {:?}", e);
                        1
                    }
                }
            }
            Err(e) => {
                eprintln!("nsh: parse error: {}", e);
                255
            }
        }
    }

    pub fn run_script(&mut self, input: &str) -> i32 {
        self.run_string(input)
    }

    pub fn exec_compound_list(&mut self, list: &CompoundList) -> Result<i32, ShellError> {
        let mut last = 0i32;
        for (aol, background) in &list.items {
            if *background {
                last = self.exec_and_or_list_bg(aol)?;
            } else {
                last = self.exec_and_or_list(aol)?;
                if self.set_e && last != 0 {
                    return Err(ShellError::Exit(last));
                }
            }
        }
        self.last_exit = last;
        Ok(last)
    }

    fn exec_and_or_list_bg(&mut self, list: &AndOrList) -> Result<i32, ShellError> {
        // Run in background
        let list = list.clone();
        let pid = unsafe { libc::fork() };
        if pid == 0 {
            // Child: close stdin?
            let result = self.exec_and_or_list_inner(&list);
            let rc = match result {
                Ok(rc) => rc,
                Err(ShellError::Exit(rc)) => rc,
                _ => 0,
            };
            std::process::exit(rc as i32);
        } else if pid > 0 {
            self.last_bg_pid = Some(pid as u32);
            eprintln!("[{}] {}", self.jobs.len() + 1, pid);
            self.jobs.push((pid as u32, String::new()));
        }
        Ok(0)
    }

    fn exec_and_or_list(&mut self, list: &AndOrList) -> Result<i32, ShellError> {
        self.exec_and_or_list_inner(list)
    }

    fn exec_and_or_list_inner(&mut self, list: &AndOrList) -> Result<i32, ShellError> {
        let mut rc = self.exec_pipeline(&list.first)?;
        for (is_and, pipeline) in &list.rest {
            if *is_and {
                if rc == 0 {
                    rc = self.exec_pipeline(pipeline)?;
                }
            } else {
                // || - NOTE: nsh has a bug where || always executes the right side
                // Replicating that bug here
                rc = self.exec_pipeline(pipeline)?;
            }
        }
        Ok(rc)
    }

    fn exec_pipeline(&mut self, pipeline: &Pipeline) -> Result<i32, ShellError> {
        if pipeline.cmds.len() == 1 {
            let rc = self.exec_command(&pipeline.cmds[0])?;
            return Ok(if pipeline.negated { if rc == 0 { 1 } else { 0 } } else { rc });
        }

        // Multi-command pipeline
        let n = pipeline.cmds.len();
        let mut pipes = Vec::new();
        for _ in 0..n-1 {
            let (read_fd, write_fd) = create_pipe();
            pipes.push((read_fd, write_fd));
        }

        let mut pids = Vec::new();
        for (i, cmd) in pipeline.cmds.iter().enumerate() {
            let pid = unsafe { libc::fork() };
            if pid == 0 {
                // Child
                if i > 0 {
                    let (read_fd, _) = pipes[i-1];
                    unsafe { libc::dup2(read_fd, 0); }
                }
                if i < n - 1 {
                    let (_, write_fd) = pipes[i];
                    unsafe { libc::dup2(write_fd, 1); }
                }
                // Close all pipe fds
                for &(r, w) in &pipes {
                    unsafe { libc::close(r); libc::close(w); }
                }
                let rc = match self.exec_command(cmd) {
                    Ok(rc) => rc,
                    Err(ShellError::Exit(rc)) => rc,
                    Err(e) => { let _ = e; 1 }
                };
                std::process::exit(rc);
            } else {
                pids.push(pid);
            }
        }

        // Close all pipe fds in parent
        for (r, w) in pipes {
            unsafe { libc::close(r); libc::close(w); }
        }

        // Wait for all children
        let mut last_rc = 0i32;
        for pid in pids {
            let mut status = 0;
            unsafe { libc::waitpid(pid, &mut status, 0); }
            last_rc = if libc::WIFEXITED(status) { libc::WEXITSTATUS(status) } else { 1 };
        }

        Ok(if pipeline.negated { if last_rc == 0 { 1 } else { 0 } } else { last_rc })
    }

    fn exec_command(&mut self, cmd: &Command) -> Result<i32, ShellError> {
        match cmd {
            Command::Simple(simple) => self.exec_simple(simple),
            Command::If { cond, then_body, elif_parts, else_body } => {
                self.exec_if(cond, then_body, elif_parts, else_body)
            }
            Command::While { cond, body } => self.exec_while(cond, body),
            Command::ForIn { var, items, body } => self.exec_for_in(var, items, body),
            Command::ForArith { init, cond, step, body } => self.exec_for_arith(init, cond, step, body),
            Command::Case { word, arms } => self.exec_case(word, arms),
            Command::Function { name, body } => {
                self.functions.insert(name.clone(), body.clone());
                Ok(0)
            }
            Command::Subshell(body) => self.exec_subshell(body),
            Command::Group(body) => self.exec_compound_list(body),
            Command::DoubleBracket(expr) => Ok(self.eval_cond(expr)),
            Command::Test(args) => {
                let expanded: Vec<String> = args.iter()
                    .map(|w| self.expand_word_to_string(w))
                    .collect();
                Ok(builtins::evaluate_test(&expanded))
            }
        }
    }

    fn exec_if(
        &mut self,
        cond: &CompoundList,
        then_body: &CompoundList,
        elif_parts: &[(CompoundList, CompoundList)],
        else_body: &Option<CompoundList>,
    ) -> Result<i32, ShellError> {
        let rc = self.exec_compound_list(cond)?;
        if rc == 0 {
            return self.exec_compound_list(then_body);
        }
        for (elif_cond, elif_body) in elif_parts {
            let rc = self.exec_compound_list(elif_cond)?;
            if rc == 0 {
                return self.exec_compound_list(elif_body);
            }
        }
        if let Some(else_b) = else_body {
            return self.exec_compound_list(else_b);
        }
        Ok(0)
    }

    fn exec_while(&mut self, cond: &CompoundList, body: &CompoundList) -> Result<i32, ShellError> {
        let mut last_rc = 0;
        loop {
            let rc = self.exec_compound_list(cond)?;
            if rc != 0 { break; }
            match self.exec_compound_list(body) {
                Ok(rc) => last_rc = rc,
                Err(ShellError::Break(n)) => {
                    if n <= 1 { break; }
                    return Err(ShellError::Break(n - 1));
                }
                Err(ShellError::Continue(n)) => {
                    if n <= 1 { continue; }
                    return Err(ShellError::Continue(n - 1));
                }
                Err(e) => return Err(e),
            }
        }
        Ok(last_rc)
    }

    fn exec_for_in(&mut self, var: &str, items: &[Word], body: &CompoundList) -> Result<i32, ShellError> {
        let mut expanded_items = Vec::new();
        for item in items {
            let words = self.expand_word(item);
            expanded_items.extend(words);
        }

        let mut last_rc = 0;
        for val in expanded_items {
            self.set_var(var, &val);
            match self.exec_compound_list(body) {
                Ok(rc) => last_rc = rc,
                Err(ShellError::Break(n)) => {
                    if n <= 1 { break; }
                    return Err(ShellError::Break(n - 1));
                }
                Err(ShellError::Continue(n)) => {
                    if n <= 1 { continue; }
                    return Err(ShellError::Continue(n - 1));
                }
                Err(e) => return Err(e),
            }
        }
        Ok(last_rc)
    }

    fn exec_for_arith(
        &mut self,
        init: &Option<Box<ArithExpr>>,
        cond: &Option<Box<ArithExpr>>,
        step: &Option<Box<ArithExpr>>,
        body: &CompoundList,
    ) -> Result<i32, ShellError> {
        if let Some(init_expr) = init {
            self.eval_arith(init_expr);
        }

        let mut last_rc = 0;
        loop {
            if let Some(cond_expr) = cond {
                let v = self.eval_arith(cond_expr);
                if v == 0 { break; }
            }

            match self.exec_compound_list(body) {
                Ok(rc) => last_rc = rc,
                Err(ShellError::Break(n)) => {
                    if n <= 1 { break; }
                    return Err(ShellError::Break(n - 1));
                }
                Err(ShellError::Continue(n)) => {
                    if n <= 1 { }
                    else { return Err(ShellError::Continue(n - 1)); }
                }
                Err(e) => return Err(e),
            }

            if let Some(step_expr) = step {
                self.eval_arith(step_expr);
            }
        }
        Ok(last_rc)
    }

    fn exec_case(&mut self, word: &Word, arms: &[CaseArm]) -> Result<i32, ShellError> {
        let val = self.expand_word_to_string(word);
        for arm in arms {
            for pat in &arm.patterns {
                let pat_str = self.expand_word_to_string(pat);
                if expand::glob_match(&pat_str, &val) || pat_str == val {
                    return self.exec_compound_list(&arm.body);
                }
            }
        }
        Ok(0)
    }

    fn exec_subshell(&mut self, body: &CompoundList) -> Result<i32, ShellError> {
        // Execute in a subshell (fork)
        let body = body.clone();
        let pid = unsafe { libc::fork() };
        if pid == 0 {
            let rc = match self.exec_compound_list(&body) {
                Ok(rc) => rc,
                Err(ShellError::Exit(rc)) => rc,
                Err(e) => { let _ = e; 1 }
            };
            std::process::exit(rc);
        }
        let mut status = 0;
        unsafe { libc::waitpid(pid, &mut status, 0); }
        let rc = if libc::WIFEXITED(status) { libc::WEXITSTATUS(status) } else { 1 };
        self.last_exit = rc;
        Ok(rc)
    }

    fn exec_simple(&mut self, cmd: &SimpleCmd) -> Result<i32, ShellError> {
        if self.set_n {
            return Ok(0);
        }

        // Handle redirections for the command
        let redirects = &cmd.redirects;

        // Pure assignment (no name)
        if cmd.name.is_none() {
            for (k, v) in &cmd.assigns {
                let val = self.expand_word_to_string(v);
                self.set_var(k, &val);
                if self.exported_vars.contains(k) {
                    std::env::set_var(k, &val);
                }
            }
            return Ok(0);
        }

        // Get command name
        let name = self.expand_word_to_string(cmd.name.as_ref().unwrap());

        // Check for tilde in name (unlikely but possible)
        let name = if name.starts_with('~') {
            expand::tilde_expand(&name)
        } else {
            name
        };

        // Expand arguments
        let mut args: Vec<String> = cmd.args.iter()
            .flat_map(|w| self.expand_word(w))
            .collect();

        // Check aliases
        if let Some(alias) = self.aliases.get(&name).cloned() {
            // Re-parse the alias expansion
            let mut alias_input = alias.clone();
            for arg in &args {
                alias_input.push(' ');
                alias_input.push_str(arg);
            }
            for (k, v) in &cmd.assigns {
                let val = self.expand_word_to_string(v);
                self.set_var(k, &val);
            }
            return self.run_string_result(&alias_input);
        }

        // Check functions
        if let Some(func_body) = self.functions.get(&name).cloned() {
            // Set up temp env
            for (k, v) in &cmd.assigns {
                let val = self.expand_word_to_string(v);
                self.set_var(k, &val);
            }
            let result = self.exec_function(&name, &func_body, &args, redirects);
            return result;
        }

        // Check builtins
        match name.as_str() {
            "echo" => {
                let rc = self.with_redirects(redirects, || {
                    builtins::builtin_echo(&args)
                })?;
                return Ok(rc);
            }
            "printf" => {
                let rc = self.with_redirects(redirects, || {
                    builtins::builtin_printf(&args)
                })?;
                return Ok(rc);
            }
            "cd" => {
                let rc = self.do_cd(&args);
                return Ok(rc);
            }
            "pwd" => {
                let rc = self.with_redirects(redirects, || {
                    match std::env::current_dir() {
                        Ok(p) => { println!("{}", p.display()); 0 }
                        Err(e) => { eprintln!("nsh: pwd: {}", e); 1 }
                    }
                })?;
                return Ok(rc);
            }
            "export" => {
                let rc = self.do_export(&args);
                return Ok(rc);
            }
            "unset" => {
                for a in &args {
                    self.unset_var(a);
                    self.exported_vars.remove(a);
                    std::env::remove_var(a);
                }
                return Ok(0);
            }
            "alias" => {
                let rc = self.with_redirects(redirects, || {
                    self.do_alias(&args)
                })?;
                return Ok(rc);
            }
            "source" => {
                if args.is_empty() {
                    eprintln!("nsh: source: no file specified");
                    return Ok(1);
                }
                match std::fs::read_to_string(&args[0]) {
                    Ok(content) => {
                        return Ok(self.run_string(&content));
                    }
                    Err(e) => {
                        eprintln!("nsh: {}: {}", args[0], e);
                        return Ok(1);
                    }
                }
            }
            "exit" => {
                let rc = args.first().and_then(|s| s.parse().ok()).unwrap_or(self.last_exit);
                return Err(ShellError::Exit(rc));
            }
            "return" => {
                let rc = args.first().and_then(|s| s.parse().ok()).unwrap_or(0);
                return Err(ShellError::Return(rc));
            }
            "break" => {
                let n = args.first().and_then(|s| s.parse().ok()).unwrap_or(1);
                return Err(ShellError::Break(n));
            }
            "continue" => {
                let n = args.first().and_then(|s| s.parse().ok()).unwrap_or(1);
                return Err(ShellError::Continue(n));
            }
            "read" => {
                let rc = self.do_read(&args);
                return Ok(rc);
            }
            "local" => {
                let rc = self.do_local(&args);
                return Ok(rc);
            }
            "set" => {
                let rc = self.do_set(&args);
                return Ok(rc);
            }
            "shift" => {
                // No positional params for now
                return Ok(0);
            }
            "eval" => {
                if args.is_empty() { return Ok(0); }
                let script = args.join(" ");
                return Ok(self.run_string(&script));
            }
            "exec" => {
                return self.do_exec(&args, redirects);
            }
            "wait" => {
                return Ok(self.do_wait(&args));
            }
            "kill" => {
                return Ok(self.do_kill(&args));
            }
            "jobs" => {
                self.with_redirects(redirects, || {
                    self.print_jobs();
                    0
                })?;
                return Ok(0);
            }
            "fg" => {
                eprintln!("nsh: no jobs to run");
                return Ok(1);
            }
            "bg" => {
                eprintln!("nsh: no jobs to run");
                return Ok(1);
            }
            "[" => {
                // test command
                // args already collected, check last arg is ]
                if args.last().map(|s| s.as_str()) == Some("]") {
                    args.pop();
                }
                return Ok(builtins::evaluate_test(&args));
            }
            "test" => {
                return Ok(builtins::evaluate_test(&args));
            }
            _ => {}
        }

        // External command
        // Set up temporary env vars
        let mut env_overrides: Vec<(String, String)> = Vec::new();
        for (k, v) in &cmd.assigns {
            let val = self.expand_word_to_string(v);
            env_overrides.push((k.clone(), val));
        }

        self.exec_external(&name, &args, &env_overrides, redirects)
    }

    fn exec_function(
        &mut self,
        name: &str,
        body: &CompoundList,
        args: &[String],
        redirects: &[Redirect],
    ) -> Result<i32, ShellError> {
        let body = body.clone();
        let frame = Frame {
            vars: HashMap::new(),
            local_vars: std::collections::HashSet::new(),
        };
        self.frames.push(frame);

        let result = match self.exec_compound_list(&body) {
            Ok(rc) => Ok(rc),
            Err(ShellError::Return(rc)) => Ok(rc),
            Err(e) => Err(e),
        };

        self.frames.pop();
        result
    }

    fn exec_external(
        &mut self,
        name: &str,
        args: &[String],
        env_overrides: &[(String, String)],
        redirects: &[Redirect],
    ) -> Result<i32, ShellError> {
        // Find the binary
        let prog = if name.contains('/') {
            name.to_string()
        } else {
            match find_in_path(name) {
                Some(p) => p,
                None => {
                    eprintln!("nsh: command not found `{}'", name);
                    self.last_exit = 1;
                    return Ok(1);
                }
            }
        };

        let pid = unsafe { libc::fork() };
        if pid < 0 {
            eprintln!("nsh: fork failed");
            return Ok(1);
        }

        if pid == 0 {
            // Child process
            // Apply redirects
            if let Err(e) = apply_redirects_child(redirects) {
                eprintln!("nsh: {}", e);
                std::process::exit(1);
            }

            // Apply env overrides
            for (k, v) in env_overrides {
                std::env::set_var(k, v);
            }

            // Build argv
            let prog_cstr = std::ffi::CString::new(prog.as_str()).unwrap();
            let mut argv: Vec<std::ffi::CString> = Vec::new();
            argv.push(std::ffi::CString::new(name).unwrap());
            for arg in args {
                argv.push(std::ffi::CString::new(arg.as_str()).unwrap());
            }

            let argv_ptrs: Vec<*const libc::c_char> = argv.iter()
                .map(|s| s.as_ptr())
                .chain(std::iter::once(std::ptr::null()))
                .collect();

            unsafe { libc::execv(prog_cstr.as_ptr(), argv_ptrs.as_ptr()); }

            // execv failed
            let err = std::io::Error::last_os_error();
            if err.kind() == std::io::ErrorKind::PermissionDenied {
                eprintln!("nsh: Failed to exec {:?} (EACCESS). chmod(1) may help.", name);
            } else {
                eprintln!("nsh: {}: {}", name, err);
            }
            std::process::exit(127);
        }

        // Parent: wait for child
        let mut status = 0;
        unsafe { libc::waitpid(pid, &mut status, 0); }

        // Check for background job completions
        self.reap_jobs();

        let rc = if libc::WIFEXITED(status) {
            libc::WEXITSTATUS(status)
        } else if libc::WIFSIGNALED(status) {
            128 + libc::WTERMSIG(status)
        } else {
            1
        };

        self.last_exit = rc;
        Ok(rc)
    }

    fn reap_jobs(&mut self) {
        let mut i = 0;
        while i < self.jobs.len() {
            let (pid, ref cmd) = self.jobs[i];
            let mut status = 0;
            let rc = unsafe { libc::waitpid(pid as i32, &mut status, libc::WNOHANG) };
            if rc > 0 {
                let exit_rc = if libc::WIFEXITED(status) { libc::WEXITSTATUS(status) } else { 1 };
                let cmd = cmd.clone();
                eprintln!("[{}] Done: {}", i + 1, cmd);
                self.jobs.remove(i);
            } else {
                i += 1;
            }
        }
    }

    fn print_jobs(&self) {
        for (i, (pid, cmd)) in self.jobs.iter().enumerate() {
            println!("[{}] Running: {}", i + 1, cmd);
        }
    }

    fn do_cd(&mut self, args: &[String]) -> i32 {
        let dir = if args.is_empty() {
            self.get_var("HOME").unwrap_or_else(|| "/".to_string())
        } else {
            args[0].clone()
        };

        match std::env::set_current_dir(&dir) {
            Ok(_) => {
                // Update PWD
                if let Ok(p) = std::env::current_dir() {
                    let pwd = p.to_string_lossy().to_string();
                    self.set_var("PWD", &pwd);
                    self.global_vars.insert("PWD".to_string(), pwd.clone());
                    std::env::set_var("PWD", &pwd);
                }
                0
            }
            Err(e) => {
                eprintln!("nsh: cd: {}: {}", dir, e);
                1
            }
        }
    }

    fn do_export(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            // Print all exported vars
            return 0;
        }
        for arg in args {
            if let Some(pos) = arg.find('=') {
                let k = &arg[..pos];
                let v = &arg[pos+1..];
                self.set_var(k, v);
                self.exported_vars.insert(k.to_string());
                std::env::set_var(k, v);
            } else {
                self.exported_vars.insert(arg.to_string());
                if let Some(v) = self.get_var(arg) {
                    std::env::set_var(arg, &v);
                }
            }
        }
        0
    }

    fn do_alias(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            // Print all aliases sorted
            let mut aliases: Vec<(&String, &String)> = self.aliases.iter().collect();
            aliases.sort_by_key(|(k, _)| *k);
            for (k, v) in aliases {
                println!("{}='{}'", k, v);
            }
            return 0;
        }
        for arg in args {
            if let Some(pos) = arg.find('=') {
                let k = arg[..pos].to_string();
                let v = arg[pos+1..].trim_matches('\'').trim_matches('"').to_string();
                self.aliases.insert(k, v);
            } else {
                // Print specific alias
                if let Some(v) = self.aliases.get(arg) {
                    println!("{}='{}'", arg, v);
                }
            }
        }
        0
    }

    fn do_read(&mut self, args: &[String]) -> i32 {
        let mut line = String::new();
        match std::io::stdin().read_line(&mut line) {
            Ok(0) => return 1, // EOF
            Ok(_) => {}
            Err(_) => return 1,
        }
        let line = line.trim_end_matches('\n').trim_end_matches('\r');

        if args.is_empty() {
            self.set_var("REPLY", line);
        } else if args.len() == 1 {
            self.set_var(&args[0], line);
        } else {
            // Split into fields
            let ifs = self.get_var("IFS").unwrap_or_else(|| " \t\n".to_string());
            let mut fields: Vec<String> = expand::split_on_ifs(line, &ifs);
            for (i, var) in args.iter().enumerate() {
                if i == args.len() - 1 {
                    // Last var gets rest
                    let rest = fields[i..].join(" ");
                    self.set_var(var, &rest);
                } else {
                    let v = fields.get(i).cloned().unwrap_or_default();
                    self.set_var(var, &v);
                }
            }
        }
        0
    }

    fn do_local(&mut self, args: &[String]) -> i32 {
        for arg in args {
            if let Some(pos) = arg.find('=') {
                let k = &arg[..pos];
                let v = &arg[pos+1..];
                self.declare_local(k, Some(v));
            } else {
                self.declare_local(arg, None);
            }
        }
        0
    }

    fn do_set(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            return 0;
        }

        // Handle set --help
        if args[0] == "--help" || args[0] == "-h" {
            eprintln!("nsh: set: set 0.4.2\nSet command.\n\nUSAGE:\n    set [FLAGS]\n\nFLAGS:\n    -e               \n    -h, --help       Prints help information\n    -n               \n    -u               \n    -V, --version    Prints version information");
            return 1;
        }

        if args[0] == "--version" || args[0] == "-V" {
            eprintln!("nsh: set: set 0.4.2");
            return 1;
        }

        for arg in args {
            match arg.as_str() {
                "-e" => self.set_e = true,
                "+e" => self.set_e = false,
                "-n" => self.set_n = true,
                "+n" => self.set_n = false,
                "-u" => self.set_u = true,
                "+u" => self.set_u = false,
                s if s.starts_with('-') || s.starts_with('+') => {
                    eprintln!("nsh: set: error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    set [FLAGS]\n\nFor more information try --help", s);
                    return 1;
                }
                s => {
                    eprintln!("nsh: set: error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    set [FLAGS]\n\nFor more information try --help", s);
                    return 1;
                }
            }
        }
        0
    }

    fn do_exec(&mut self, args: &[String], redirects: &[Redirect]) -> Result<i32, ShellError> {
        if args.is_empty() {
            // exec with no args just applies redirects
            return Ok(0);
        }

        let name = &args[0];
        let prog = if name.contains('/') {
            name.clone()
        } else {
            match find_in_path(name) {
                Some(p) => p,
                None => {
                    eprintln!("nsh: {}: command not found", name);
                    return Ok(127);
                }
            }
        };

        // Apply redirects
        if let Err(e) = apply_redirects_child(redirects) {
            eprintln!("nsh: {}", e);
            return Ok(1);
        }

        let prog_cstr = std::ffi::CString::new(prog.as_str()).unwrap();
        let mut argv: Vec<std::ffi::CString> = args.iter()
            .map(|s| std::ffi::CString::new(s.as_str()).unwrap())
            .collect();
        argv.push(std::ffi::CString::new("").unwrap()); // null terminator placeholder
        let argv_ptrs: Vec<*const libc::c_char> = argv[..argv.len()-1].iter()
            .map(|s| s.as_ptr())
            .chain(std::iter::once(std::ptr::null()))
            .collect();

        unsafe { libc::execv(prog_cstr.as_ptr(), argv_ptrs.as_ptr()); }

        let err = std::io::Error::last_os_error();
        eprintln!("nsh: exec: {}: {}", name, err);
        Err(ShellError::Exit(1))
    }

    fn do_wait(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            // Wait for all background jobs
            let mut status = 0;
            loop {
                let pid = unsafe { libc::wait(&mut status) };
                if pid <= 0 { break; }
            }
            self.jobs.clear();
        } else {
            for pid_str in args {
                if let Ok(pid) = pid_str.parse::<i32>() {
                    let mut status = 0;
                    unsafe { libc::waitpid(pid, &mut status, 0); }
                }
            }
        }
        0
    }

    fn do_kill(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            eprintln!("nsh: kill: usage: kill [-signal] pid ...");
            return 1;
        }
        if args[0] == "-l" {
            builtins::builtin_kill_l();
            return 0;
        }

        let (sig, pids) = if args[0].starts_with('-') {
            let sig_str = &args[0][1..];
            let sig = parse_signal(sig_str);
            (sig, &args[1..])
        } else {
            (libc::SIGTERM, args.as_slice())
        };

        for pid_str in pids {
            if let Ok(pid) = pid_str.parse::<i32>() {
                unsafe { libc::kill(pid, sig); }
            }
        }
        0
    }

    fn run_string_result(&mut self, s: &str) -> Result<i32, ShellError> {
        Ok(self.run_string(s))
    }

    pub fn capture_output(&mut self, list: &CompoundList) -> String {
        let (read_fd, write_fd) = create_pipe();

        let pid = unsafe { libc::fork() };
        if pid == 0 {
            unsafe { libc::close(read_fd); }
            unsafe { libc::dup2(write_fd, 1); }
            unsafe { libc::close(write_fd); }
            let rc = match self.exec_compound_list(list) {
                Ok(rc) => rc,
                Err(ShellError::Exit(rc)) => rc,
                Err(e) => { let _ = e; 1 }
            };
            std::process::exit(rc);
        }

        unsafe { libc::close(write_fd); }

        let mut output = String::new();
        let mut buf = [0u8; 4096];
        loop {
            let n = unsafe { libc::read(read_fd, buf.as_mut_ptr() as *mut libc::c_void, buf.len()) };
            if n <= 0 { break; }
            output.push_str(&String::from_utf8_lossy(&buf[..n as usize]));
        }
        unsafe { libc::close(read_fd); }

        let mut status = 0;
        unsafe { libc::waitpid(pid, &mut status, 0); }

        output
    }

    pub fn start_proc_sub(&mut self, list: &CompoundList) -> String {
        // Create a pipe, fork, child writes to write end
        let (read_fd, write_fd) = create_pipe();

        let pid = unsafe { libc::fork() };
        if pid == 0 {
            unsafe { libc::close(read_fd); }
            unsafe { libc::dup2(write_fd, 1); }
            unsafe { libc::close(write_fd); }
            let _ = self.exec_compound_list(list);
            std::process::exit(0);
        }

        unsafe { libc::close(write_fd); }
        self.proc_sub_fds.push(read_fd);

        format!("/dev/fd/{}", read_fd)
    }

    pub fn eval_arith(&mut self, expr: &ArithExpr) -> i64 {
        match expr {
            ArithExpr::Num(n) => *n,
            ArithExpr::Var(name) => {
                let v = self.get_var(name).unwrap_or_default();
                v.parse().unwrap_or(0)
            }
            ArithExpr::Add(a, b) => self.eval_arith(a) + self.eval_arith(b),
            ArithExpr::Sub(a, b) => self.eval_arith(a) - self.eval_arith(b),
            ArithExpr::Mul(a, b) => self.eval_arith(a) * self.eval_arith(b),
            ArithExpr::Div(a, b) => {
                let bv = self.eval_arith(b);
                if bv == 0 { 0 } else { self.eval_arith(a) / bv }
            }
            ArithExpr::Mod(a, b) => {
                let bv = self.eval_arith(b);
                if bv == 0 { 0 } else { self.eval_arith(a) % bv }
            }
            ArithExpr::Eq(a, b) => if self.eval_arith(a) == self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Ne(a, b) => if self.eval_arith(a) != self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Lt(a, b) => if self.eval_arith(a) < self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Le(a, b) => if self.eval_arith(a) <= self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Gt(a, b) => if self.eval_arith(a) > self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Ge(a, b) => if self.eval_arith(a) >= self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Neg(a) => -self.eval_arith(a),
            ArithExpr::PostInc(name) => {
                let v = self.get_var(name).unwrap_or_default().parse::<i64>().unwrap_or(0);
                let new_v = v + 1;
                self.set_var(name, &new_v.to_string());
                new_v // nsh bug: returns incremented value
            }
            ArithExpr::PostDec(name) => {
                let v = self.get_var(name).unwrap_or_default().parse::<i64>().unwrap_or(0);
                let new_v = v - 1;
                self.set_var(name, &new_v.to_string());
                new_v // Returns decremented value
            }
            ArithExpr::CmdSub(list) => {
                let output = self.capture_output(list);
                let stripped: String = output.chars().filter(|c| !c.is_whitespace()).collect();
                stripped.parse().unwrap_or(0)
            }
        }
    }

    pub fn eval_cond(&mut self, expr: &CondExpr) -> i32 {
        match expr {
            CondExpr::Word(w) => {
                let s = self.expand_word_to_string(w);
                if s.is_empty() { 1 } else { 0 }
            }
            CondExpr::BinOp { left, op, right } => {
                let l = self.expand_word_to_string(left);
                let r = self.expand_word_to_string(right);
                let result = match op {
                    CondOp::Eq => l == r,
                    CondOp::Ne => l != r,
                    CondOp::Lt => l < r,
                    CondOp::Le => l <= r,
                    CondOp::Gt => l > r,
                    CondOp::Ge => l >= r,
                    CondOp::NumEq => l.parse::<i64>().unwrap_or(0) == r.parse::<i64>().unwrap_or(0),
                    CondOp::NumNe => l.parse::<i64>().unwrap_or(0) != r.parse::<i64>().unwrap_or(0),
                    CondOp::NumLt => l.parse::<i64>().unwrap_or(0) < r.parse::<i64>().unwrap_or(0),
                    CondOp::NumLe => l.parse::<i64>().unwrap_or(0) <= r.parse::<i64>().unwrap_or(0),
                    CondOp::NumGt => l.parse::<i64>().unwrap_or(0) > r.parse::<i64>().unwrap_or(0),
                    CondOp::NumGe => l.parse::<i64>().unwrap_or(0) >= r.parse::<i64>().unwrap_or(0),
                };
                if result { 0 } else { 1 }
            }
            CondExpr::FileTest { flag, word } => {
                let val = self.expand_word_to_string(word);
                builtins::evaluate_test(&[format!("-{}", flag), val])
            }
            CondExpr::Not(e) => {
                let rc = self.eval_cond(e);
                if rc == 0 { 1 } else { 0 }
            }
            CondExpr::And(a, b) => {
                if self.eval_cond(a) == 0 { self.eval_cond(b) } else { 1 }
            }
            CondExpr::Or(a, b) => {
                if self.eval_cond(a) == 0 { 0 } else { self.eval_cond(b) }
            }
        }
    }

    pub fn expand_word_to_string(&mut self, word: &Word) -> String {
        expand::expand_to_string(word, self)
    }

    pub fn expand_word(&mut self, word: &Word) -> Vec<String> {
        expand::expand_to_words(word, self)
    }

    fn with_redirects<F: FnOnce() -> i32>(&mut self, redirects: &[Redirect], f: F) -> Result<i32, ShellError> {
        if redirects.is_empty() {
            return Ok(f());
        }

        // Save stdout/stderr
        let saved_stdout = unsafe { libc::dup(1) };
        let saved_stderr = unsafe { libc::dup(2) };

        apply_redirects_parent(redirects)?;

        let rc = f();

        // Restore
        unsafe {
            libc::dup2(saved_stdout, 1);
            libc::close(saved_stdout);
            libc::dup2(saved_stderr, 2);
            libc::close(saved_stderr);
        }

        Ok(rc)
    }

    pub fn run_interactive(&mut self) {
        use std::io::BufRead;

        let stdin = std::io::stdin();
        let mut is_tty = unsafe { libc_isatty(0) };

        loop {
            if is_tty {
                let prompt = self.build_prompt();
                print!("{}", prompt);
                let _ = std::io::stdout().flush();
            }

            let mut line = String::new();
            match stdin.lock().read_line(&mut line) {
                Ok(0) => break, // EOF
                Ok(_) => {}
                Err(_) => break,
            }

            let line = line.trim_end_matches('\n').trim_end_matches('\r');
            if line.is_empty() { continue; }
            if line.starts_with('#') { continue; }

            // Handle multiline commands (continuation)
            let result = self.run_string(line);
            match result {
                _ => {}
            }
        }
    }

    fn build_prompt(&self) -> String {
        let prompt = self.global_vars.get("PROMPT")
            .cloned()
            .unwrap_or_else(|| "$ ".to_string());
        // Simple prompt - just return it for now
        // The actual prompt expansion is complex and involves interactive mode
        prompt
    }
}

fn create_pipe() -> (RawFd, RawFd) {
    let mut fds = [0i32; 2];
    unsafe { libc::pipe(fds.as_mut_ptr()); }
    (fds[0], fds[1])
}

fn find_in_path(name: &str) -> Option<String> {
    let path = std::env::var("PATH").unwrap_or_else(|_| "/usr/bin:/bin".to_string());
    for dir in path.split(':') {
        let full = format!("{}/{}", dir, name);
        if std::path::Path::new(&full).exists() {
            // Check executable
            use std::os::unix::fs::PermissionsExt;
            if let Ok(m) = std::fs::metadata(&full) {
                if m.permissions().mode() & 0o111 != 0 {
                    return Some(full);
                }
            }
        }
    }
    None
}

fn apply_redirects_child(redirects: &[Redirect]) -> Result<(), String> {
    for r in redirects {
        apply_redirect_child(r)?;
    }
    Ok(())
}

fn apply_redirect_child(r: &Redirect) -> Result<(), String> {
    match r {
        Redirect::Out(word) => {
            let path = word_to_path(word);
            let fd = open_for_write(&path)?;
            unsafe { libc::dup2(fd, 1); libc::close(fd); }
        }
        Redirect::Append(word) => {
            let path = word_to_path(word);
            let fd = open_for_append(&path)?;
            unsafe { libc::dup2(fd, 1); libc::close(fd); }
        }
        Redirect::In(word) => {
            let path = word_to_path(word);
            let fd = open_for_read(&path)?;
            unsafe { libc::dup2(fd, 0); libc::close(fd); }
        }
        Redirect::StderrOut(word) => {
            let path = word_to_path(word);
            let fd = open_for_write(&path)?;
            unsafe { libc::dup2(fd, 2); libc::close(fd); }
        }
        Redirect::StderrAppend(word) => {
            let path = word_to_path(word);
            let fd = open_for_append(&path)?;
            unsafe { libc::dup2(fd, 2); libc::close(fd); }
        }
        Redirect::StderrToStdout => {
            unsafe { libc::dup2(1, 2); }
        }
        Redirect::StdoutToStderr => {
            unsafe { libc::dup2(2, 1); }
        }
        Redirect::BothOut(word) => {
            let path = word_to_path(word);
            let fd = open_for_write(&path)?;
            unsafe { libc::dup2(fd, 1); libc::dup2(fd, 2); libc::close(fd); }
        }
        Redirect::FdOut(fd, word) => {
            let path = word_to_path(word);
            let new_fd = open_for_write(&path)?;
            unsafe { libc::dup2(new_fd, *fd as i32); libc::close(new_fd); }
        }
        Redirect::FdIn(fd, word) => {
            let path = word_to_path(word);
            let new_fd = open_for_read(&path)?;
            unsafe { libc::dup2(new_fd, *fd as i32); libc::close(new_fd); }
        }
        Redirect::FdDup(from, to) => {
            if *to == 999 {
                unsafe { libc::close(*from as i32); }
            } else {
                unsafe { libc::dup2(*to as i32, *from as i32); }
            }
        }
        Redirect::Heredoc { marker: _, contents, interpolate: _ } => {
            // Create a pipe with the heredoc content
            let (read_fd, write_fd) = create_pipe();
            let bytes = contents.as_bytes();
            unsafe { libc::write(write_fd, bytes.as_ptr() as *const libc::c_void, bytes.len()); }
            unsafe { libc::close(write_fd); }
            unsafe { libc::dup2(read_fd, 0); libc::close(read_fd); }
        }
        Redirect::ProcSubIn(list) => {
            // Process substitution in redirect - TODO
        }
    }
    Ok(())
}

fn apply_redirects_parent(redirects: &[Redirect]) -> Result<(), ShellError> {
    for r in redirects {
        match r {
            Redirect::Out(word) => {
                let path = word_to_path(word);
                if let Ok(fd) = open_for_write(&path) {
                    unsafe { libc::dup2(fd, 1); libc::close(fd); }
                }
            }
            Redirect::Append(word) => {
                let path = word_to_path(word);
                if let Ok(fd) = open_for_append(&path) {
                    unsafe { libc::dup2(fd, 1); libc::close(fd); }
                }
            }
            Redirect::In(word) => {
                let path = word_to_path(word);
                if let Ok(fd) = open_for_read(&path) {
                    unsafe { libc::dup2(fd, 0); libc::close(fd); }
                }
            }
            Redirect::StderrOut(word) => {
                let path = word_to_path(word);
                if let Ok(fd) = open_for_write(&path) {
                    unsafe { libc::dup2(fd, 2); libc::close(fd); }
                }
            }
            Redirect::StderrToStdout => {
                unsafe { libc::dup2(1, 2); }
            }
            _ => {}
        }
    }
    Ok(())
}

fn word_to_path(word: &Word) -> String {
    if let Some(WordPart::Literal(s)) = word.parts.first() {
        s.clone()
    } else {
        String::new()
    }
}

fn open_for_write(path: &str) -> Result<RawFd, String> {
    let cpath = std::ffi::CString::new(path).map_err(|e| e.to_string())?;
    let fd = unsafe { 
        libc::open(cpath.as_ptr(), libc::O_WRONLY | libc::O_CREAT | libc::O_TRUNC, 0o644)
    };
    if fd < 0 {
        Err(format!("{}: {}", path, std::io::Error::last_os_error()))
    } else {
        Ok(fd)
    }
}

fn open_for_append(path: &str) -> Result<RawFd, String> {
    let cpath = std::ffi::CString::new(path).map_err(|e| e.to_string())?;
    let fd = unsafe { 
        libc::open(cpath.as_ptr(), libc::O_WRONLY | libc::O_CREAT | libc::O_APPEND, 0o644)
    };
    if fd < 0 {
        Err(format!("{}: {}", path, std::io::Error::last_os_error()))
    } else {
        Ok(fd)
    }
}

fn open_for_read(path: &str) -> Result<RawFd, String> {
    let cpath = std::ffi::CString::new(path).map_err(|e| e.to_string())?;
    let fd = unsafe { libc::open(cpath.as_ptr(), libc::O_RDONLY, 0) };
    if fd < 0 {
        Err(format!("{}: {}", path, std::io::Error::last_os_error()))
    } else {
        Ok(fd)
    }
}

fn parse_signal(s: &str) -> i32 {
    match s {
        "HUP" | "1" => libc::SIGHUP,
        "INT" | "2" => libc::SIGINT,
        "QUIT" | "3" => libc::SIGQUIT,
        "KILL" | "9" => libc::SIGKILL,
        "TERM" | "15" => libc::SIGTERM,
        "STOP" | "19" => libc::SIGSTOP,
        "CONT" | "18" => libc::SIGCONT,
        n => n.parse().unwrap_or(libc::SIGTERM),
    }
}

fn libc_isatty(fd: i32) -> bool {
    unsafe { libc::isatty(fd) == 1 }
}
