    fn exec_aol(&mut self, aol: &AndOrList) -> Result<i32, ExecError> {
        let mut rc = self.exec_pipeline(&aol.first)?;
        for (is_and, pipeline) in &aol.rest {
            if *is_and {
                // && - only execute right if left succeeded
                if rc == 0 {
                    rc = self.exec_pipeline(pipeline)?;
                }
            } else {
                // || - nsh bug: always executes right side
                rc = self.exec_pipeline(pipeline)?;
            }
        }
        Ok(rc)
    }

    fn exec_pipeline(&mut self, p: &Pipeline) -> Result<i32, ExecError> {
        let rc = if p.cmds.len() == 1 {
            self.exec_cmd(&p.cmds[0])?
        } else {
            self.exec_pipe(&p.cmds)?
        };
        Ok(if p.negated { if rc == 0 { 1 } else { 0 } } else { rc })
    }

    fn exec_pipe(&mut self, cmds: &[Command]) -> Result<i32, ExecError> {
        let n = cmds.len();
        let mut pipes: Vec<(i32, i32)> = Vec::new();
        for _ in 0..n-1 {
            let mut fds = [0i32; 2];
            unsafe { sys::pipe(fds.as_mut_ptr()); }
            pipes.push((fds[0], fds[1]));
        }

        let mut pids = Vec::new();
        for (i, cmd) in cmds.iter().enumerate() {
            let pid = unsafe { sys::fork() };
            if pid == 0 {
                // Set up stdin from prev pipe
                if i > 0 {
                    unsafe { sys::dup2(pipes[i-1].0, 0); }
                }
                // Set up stdout to next pipe
                if i < n - 1 {
                    unsafe { sys::dup2(pipes[i].1, 1); }
                }
                // Close all pipe fds
                for &(r, w) in &pipes {
                    unsafe { sys::close(r); sys::close(w); }
                }
                let rc = match self.exec_cmd(cmd) {
                    Ok(rc) => rc,
                    Err(ExecError::Exit(rc)) => rc,
                    Err(_) => 1,
                };
                std::process::exit(rc);
            }
            if pid > 0 { pids.push(pid); }
        }

        for &(r, w) in &pipes {
            unsafe { sys::close(r); sys::close(w); }
        }

        let mut last_rc = 0;
        for pid in pids {
            let mut status = 0;
            unsafe { sys::waitpid(pid, &mut status, 0); }
            last_rc = if WIFEXITED(status) { WEXITSTATUS(status) } else { 1 };
        }

        Ok(last_rc)
    }

    fn exec_cmd(&mut self, cmd: &Command) -> Result<i32, ExecError> {
        match cmd {
