                    .map(|w| self.expand_word_to_str(w))
                    .collect();
                Ok(builtins::evaluate_test(&expanded))
            }
        }
    }

    fn exec_if(&mut self, cond: &CompoundList, then_b: &CompoundList, 
               elif_parts: &[(CompoundList, CompoundList)],
               else_b: &Option<CompoundList>) -> Result<i32, ExecError> {
        let rc = self.exec_list(cond)?;
        if rc == 0 { return self.exec_list(then_b); }
        for (ec, eb) in elif_parts {
            if self.exec_list(ec)? == 0 { return self.exec_list(eb); }
        }
        if let Some(e) = else_b { return self.exec_list(e); }
        Ok(0)
    }

    fn exec_while(&mut self, cond: &CompoundList, body: &CompoundList) -> Result<i32, ExecError> {
        let mut rc = 0;
        loop {
            if self.exec_list(cond)? != 0 { break; }
            match self.exec_list(body) {
                Ok(r) => rc = r,
                Err(ExecError::Break(n)) => { if n <= 1 { break; } return Err(ExecError::Break(n-1)); }
                Err(ExecError::Continue(n)) => { if n <= 1 { continue; } return Err(ExecError::Continue(n-1)); }
                Err(e) => return Err(e),
            }
        }
        Ok(rc)
    }

    fn exec_for_in(&mut self, var: &str, items: &[Word], body: &CompoundList) -> Result<i32, ExecError> {
        let vals: Vec<String> = items.iter().flat_map(|w| self.expand_word(w)).collect();
        let mut rc = 0;
