#![allow(unused, dead_code, non_snake_case)]
use crate::types::*;
use crate::expand;
use crate::builtins;
use crate::parser;
use crate::sys;
use std::collections::{HashMap, HashSet};
use std::io::{self, Write, Read};
use std::ffi::CString;

fn WIFEXITED(s: i32) -> bool { (s & 0x7f) == 0 }
fn WEXITSTATUS(s: i32) -> i32 { (s >> 8) & 0xff }
fn WIFSIGNALED(s: i32) -> bool { (((s & 0x7f) + 1) as i8) >= 2 }
fn WTERMSIG(s: i32) -> i32 { s & 0x7f }

#[derive(Debug)]
pub enum ExecError {
    Return(i32),
    Break(i32),
    Continue(i32),
    Exit(i32),
}

pub struct Frame {
    pub vars: HashMap<String, String>,
    pub locals: HashSet<String>,
}

pub struct Shell {
    pub global_vars: HashMap<String, String>,
    pub exported: HashSet<String>,
    pub aliases: HashMap<String, String>,
    pub functions: HashMap<String, CompoundList>,
    pub frames: Vec<Frame>,
    pub last_exit: i32,
    pub shell_pid: i32,
    pub last_bg_pid: Option<i32>,
    pub jobs: Vec<(i32, String)>,
    pub set_e: bool,
    pub set_u: bool,
    pub set_n: bool,
}

impl Shell {
    pub fn new() -> Self {
        let mut global_vars = HashMap::new();
        let mut exported = HashSet::new();
        for (k, v) in std::env::vars() {
            exported.insert(k.clone());
            global_vars.insert(k, v);
        }
        if !global_vars.contains_key("IFS") {
            global_vars.insert("IFS".to_string(), " \t\n".to_string());
        }
        Shell {
            global_vars,
            exported,
            aliases: HashMap::new(),
            functions: HashMap::new(),
            frames: Vec::new(),
            last_exit: 0,
            shell_pid: unsafe { sys::getpid() },
            last_bg_pid: None,
            jobs: Vec::new(),
            set_e: false,
            set_u: false,
            set_n: false,
        }
    }

    pub fn get_var(&self, name: &str) -> Option<String> {
        match name {
            "?" => return Some(self.last_exit.to_string()),
            "$" => return Some(self.shell_pid.to_string()),
            "!" => return Some(self.last_bg_pid.map(|p| p.to_string()).unwrap_or_default()),
            "0" => return Some("nsh".to_string()),
            "#" => return Some("0".to_string()),
            "@" | "*" => return Some(String::new()),
            "-" => return Some(String::new()),
            _ => {}
        }
        // Check frames (innermost first)
        for frame in self.frames.iter().rev() {
            if let Some(v) = frame.vars.get(name) {
                return Some(v.clone());
            }
        }
        self.global_vars.get(name).cloned()
    }

    pub fn set_var(&mut self, name: &str, val: &str) {
        // Check if local in current frame
        for frame in self.frames.iter_mut().rev() {
            if frame.locals.contains(name) {
                frame.vars.insert(name.to_string(), val.to_string());
                return;
            }
        }
        self.global_vars.insert(name.to_string(), val.to_string());
        if self.exported.contains(name) {
            std::env::set_var(name, val);
        }
    }

    pub fn declare_local(&mut self, name: &str, val: Option<&str>) {
        if let Some(frame) = self.frames.last_mut() {
            frame.locals.insert(name.to_string());
            frame.vars.insert(name.to_string(), val.unwrap_or("").to_string());
        } else {
            self.global_vars.insert(name.to_string(), val.unwrap_or("").to_string());
        }
    }

    pub fn unset_var(&mut self, name: &str) {
        for frame in self.frames.iter_mut().rev() {
            if frame.locals.contains(name) {
                frame.vars.remove(name);
                return;
            }
        }
        self.global_vars.remove(name);
        std::env::remove_var(name);
    }

    pub fn run_string(&mut self, input: &str) -> i32 {
        match parser::parse(input) {
            Ok(list) => match self.exec_list(&list) {
                Ok(rc) => rc,
                Err(ExecError::Exit(rc)) => {
                    // Propagate via process exit for top-level
                    rc
                }
                Err(ExecError::Return(rc)) => rc,
                Err(e) => { eprintln!("nsh: internal error: {:?}", e); 1 }
            }
            Err(e) => {
                eprintln!("nsh: parse error: {}", e);
                255
            }
        }
    }

    pub fn run_script(&mut self, content: &str) -> i32 {
        self.run_string(content)
    }

    pub fn exec_list(&mut self, list: &CompoundList) -> Result<i32, ExecError> {
        let mut rc = 0;
        for (aol, bg) in &list.items {
            if *bg {
                rc = self.exec_aol_bg(aol)?;
            } else {
                rc = self.exec_aol(aol)?;
                if self.set_e && rc != 0 {
                    return Err(ExecError::Exit(rc));
                }
            }
        }
        self.last_exit = rc;
        Ok(rc)
    }

    fn exec_aol_bg(&mut self, aol: &AndOrList) -> Result<i32, ExecError> {
        let aol = aol.clone();
        let pid = unsafe { sys::fork() };
        if pid == 0 {
            let rc = match self.exec_aol(&aol) {
                Ok(rc) => rc,
                Err(ExecError::Exit(rc)) => rc,
                Err(_) => 0,
            };
            std::process::exit(rc);
        }
        if pid > 0 {
            self.last_bg_pid = Some(pid);
            self.jobs.push((pid, String::new()));
            eprintln!("[{}] {}", self.jobs.len(), pid);
        }
        Ok(0)
    }

    fn exec_aol(&mut self, aol: &AndOrList) -> Result<i32, ExecError> {
        let mut rc = self.exec_pipeline(&aol.first)?;
        for (is_and, pipeline) in &aol.rest {
            if *is_and {
                // && - only execute right if left succeeded
                if rc == 0 {
                    rc = self.exec_pipeline(pipeline)?;
                }
            } else {
                // || - nsh bug: always executes right side
                rc = self.exec_pipeline(pipeline)?;
            }
        }
        Ok(rc)
    }

    fn exec_pipeline(&mut self, p: &Pipeline) -> Result<i32, ExecError> {
        let rc = if p.cmds.len() == 1 {
            self.exec_cmd(&p.cmds[0])?
        } else {
            self.exec_pipe(&p.cmds)?
        };
        Ok(if p.negated { if rc == 0 { 1 } else { 0 } } else { rc })
    }

    fn exec_pipe(&mut self, cmds: &[Command]) -> Result<i32, ExecError> {
        let n = cmds.len();
        let mut pipes: Vec<(i32, i32)> = Vec::new();
        for _ in 0..n-1 {
            let mut fds = [0i32; 2];
            unsafe { sys::pipe(fds.as_mut_ptr()); }
            pipes.push((fds[0], fds[1]));
        }

        let mut pids = Vec::new();
        for (i, cmd) in cmds.iter().enumerate() {
            let pid = unsafe { sys::fork() };
            if pid == 0 {
                // Set up stdin from prev pipe
                if i > 0 {
                    unsafe { sys::dup2(pipes[i-1].0, 0); }
                }
                // Set up stdout to next pipe
                if i < n - 1 {
                    unsafe { sys::dup2(pipes[i].1, 1); }
                }
                // Close all pipe fds
                for &(r, w) in &pipes {
                    unsafe { sys::close(r); sys::close(w); }
                }
                let rc = match self.exec_cmd(cmd) {
                    Ok(rc) => rc,
                    Err(ExecError::Exit(rc)) => rc,
                    Err(_) => 1,
                };
                std::process::exit(rc);
            }
            if pid > 0 { pids.push(pid); }
        }

        for &(r, w) in &pipes {
            unsafe { sys::close(r); sys::close(w); }
        }

        let mut last_rc = 0;
        for pid in pids {
            let mut status = 0;
            unsafe { sys::waitpid(pid, &mut status, 0); }
            last_rc = if WIFEXITED(status) { WEXITSTATUS(status) } else { 1 };
        }

        Ok(last_rc)
    }

    fn exec_cmd(&mut self, cmd: &Command) -> Result<i32, ExecError> {
        match cmd {
            Command::Simple(s) => self.exec_simple(s),
            Command::If { cond, then_body, elif_parts, else_body } => {
                self.exec_if(cond, then_body, elif_parts, else_body)
            }
            Command::While { cond, body } => self.exec_while(cond, body),
            Command::ForIn { var, items, body } => self.exec_for_in(var, items, body),
            Command::ForArith { init, cond, step, body } => {
                self.exec_for_arith(init.as_deref(), cond.as_deref(), step.as_deref(), body)
            }
            Command::Case { word, arms } => self.exec_case(word, arms),
            Command::Function { name, body } => {
                self.functions.insert(name.clone(), body.clone());
                Ok(0)
            }
            Command::Subshell(body) => self.exec_subshell(body),
            Command::Group(body) => self.exec_list(body),
            Command::DoubleBracket(expr) => Ok(self.eval_cond(expr)),
            Command::Test(args) => {
                let expanded: Vec<String> = args.iter()
                    .map(|w| self.expand_word_to_str(w))
                    .collect();
                Ok(builtins::evaluate_test(&expanded))
            }
        }
    }

    fn exec_if(&mut self, cond: &CompoundList, then_b: &CompoundList, 
               elif_parts: &[(CompoundList, CompoundList)],
               else_b: &Option<CompoundList>) -> Result<i32, ExecError> {
        let rc = self.exec_list(cond)?;
        if rc == 0 { return self.exec_list(then_b); }
        for (ec, eb) in elif_parts {
            if self.exec_list(ec)? == 0 { return self.exec_list(eb); }
        }
        if let Some(e) = else_b { return self.exec_list(e); }
        Ok(0)
    }

    fn exec_while(&mut self, cond: &CompoundList, body: &CompoundList) -> Result<i32, ExecError> {
        let mut rc = 0;
        loop {
            if self.exec_list(cond)? != 0 { break; }
            match self.exec_list(body) {
                Ok(r) => rc = r,
                Err(ExecError::Break(n)) => { if n <= 1 { break; } return Err(ExecError::Break(n-1)); }
                Err(ExecError::Continue(n)) => { if n <= 1 { continue; } return Err(ExecError::Continue(n-1)); }
                Err(e) => return Err(e),
            }
        }
        Ok(rc)
    }

    fn exec_for_in(&mut self, var: &str, items: &[Word], body: &CompoundList) -> Result<i32, ExecError> {
        let vals: Vec<String> = items.iter().flat_map(|w| self.expand_word(w)).collect();
        let mut rc = 0;
        for val in vals {
            self.set_var(var, &val);
            match self.exec_list(body) {
                Ok(r) => rc = r,
                Err(ExecError::Break(n)) => { if n <= 1 { break; } return Err(ExecError::Break(n-1)); }
                Err(ExecError::Continue(n)) => { if n <= 1 { continue; } return Err(ExecError::Continue(n-1)); }
                Err(e) => return Err(e),
            }
        }
        Ok(rc)
    }

    fn exec_for_arith(&mut self, init: Option<&ArithExpr>, cond: Option<&ArithExpr>, 
                      step: Option<&ArithExpr>, body: &CompoundList) -> Result<i32, ExecError> {
        if let Some(e) = init { self.eval_arith(e); }
        let mut rc = 0;
        loop {
            if let Some(e) = cond { if self.eval_arith(e) == 0 { break; } }
            match self.exec_list(body) {
                Ok(r) => rc = r,
                Err(ExecError::Break(n)) => { if n <= 1 { break; } return Err(ExecError::Break(n-1)); }
                Err(ExecError::Continue(n)) => { if n <= 1 {} else { return Err(ExecError::Continue(n-1)); } }
                Err(e) => return Err(e),
            }
            if let Some(e) = step { self.eval_arith(e); }
        }
        Ok(rc)
    }

    fn exec_case(&mut self, word: &Word, arms: &[CaseArm]) -> Result<i32, ExecError> {
        let val = self.expand_word_to_str(word);
        for arm in arms {
            for pat in &arm.patterns {
                let p = self.expand_word_to_str(pat);
                if expand::glob_match(&p, &val) {
                    return self.exec_list(&arm.body);
                }
            }
        }
        Ok(0)
    }

    fn exec_subshell(&mut self, body: &CompoundList) -> Result<i32, ExecError> {
        let body = body.clone();
        let pid = unsafe { sys::fork() };
        if pid == 0 {
            let rc = match self.exec_list(&body) {
                Ok(rc) => rc,
                Err(ExecError::Exit(rc)) => rc,
                Err(_) => 1,
            };
            std::process::exit(rc);
        }
        let mut status = 0;
        unsafe { sys::waitpid(pid, &mut status, 0); }
        let rc = if WIFEXITED(status) { WEXITSTATUS(status) } else { 1 };
        self.last_exit = rc;
        Ok(rc)
    }

    fn exec_simple(&mut self, cmd: &SimpleCmd) -> Result<i32, ExecError> {
        if self.set_n { return Ok(0); }

        // Pure assignment
        if cmd.name.is_none() {
            for (k, v) in &cmd.assigns {
                let val = self.expand_word_to_str(v);
                self.set_var(k, &val);
                if self.exported.contains(k) { std::env::set_var(k, &val); }
            }
            return Ok(0);
        }

        let name_word = cmd.name.as_ref().unwrap();
        let name = self.expand_word_to_str(name_word);
        let name = if name.starts_with('~') { expand::tilde_expand(&name) } else { name };

        // Expand arguments
        let mut args: Vec<String> = cmd.args.iter()
            .flat_map(|w| self.expand_word(w))
            .collect();

        // Check alias
        if let Some(alias_val) = self.aliases.get(&name).cloned() {
            let mut full = alias_val.clone();
            for a in &args { full.push(' '); full.push_str(a); }
            for (k, v) in &cmd.assigns {
                let val = self.expand_word_to_str(v);
                self.set_var(k, &val);
            }
            return Ok(self.run_string(&full));
        }

        // Check function
        if let Some(func) = self.functions.get(&name).cloned() {
            for (k, v) in &cmd.assigns {
                let val = self.expand_word_to_str(v);
                self.set_var(k, &val);
            }
            return self.call_function(&name, &func, &args, &cmd.redirects);
        }

        // Builtins
        match name.as_str() {
            "echo" => {
                let rc = self.with_redirects(&cmd.redirects, || builtins::builtin_echo(&args))?;
                return Ok(rc);
            }
            "printf" => {
                let rc = self.with_redirects(&cmd.redirects, || builtins::builtin_printf(&args))?;
                return Ok(rc);
            }
            "cd" => return Ok(self.do_cd(&args)),
            "pwd" => {
                let rc = self.with_redirects(&cmd.redirects, || {
                    match std::env::current_dir() {
                        Ok(p) => { println!("{}", p.display()); 0 }
                        Err(e) => { eprintln!("nsh: pwd: {}", e); 1 }
                    }
                })?;
                return Ok(rc);
            }
            "export" => return Ok(self.do_export(&args)),
            "unset" => {
                for a in &args { self.unset_var(a); }
                return Ok(0);
            }
            "alias" => {
                let rc = self.with_redirects(&cmd.redirects, || self.do_alias(&args))?;
                return Ok(rc);
            }
            "source" => {
                if args.is_empty() { eprintln!("nsh: source: no file"); return Ok(1); }
                match std::fs::read_to_string(&args[0]) {
                    Ok(content) => return Ok(self.run_string(&content)),
                    Err(e) => { eprintln!("nsh: {}: {}", args[0], e); return Ok(1); }
                }
            }
            "exit" => {
                let rc = args.first().and_then(|s| s.parse().ok()).unwrap_or(self.last_exit);
                return Err(ExecError::Exit(rc));
            }
            "return" => {
                let rc = args.first().and_then(|s| s.parse().ok()).unwrap_or(0);
                return Err(ExecError::Return(rc));
            }
            "break" => {
                let n = args.first().and_then(|s| s.parse().ok()).unwrap_or(1);
                return Err(ExecError::Break(n));
            }
            "continue" => {
                let n = args.first().and_then(|s| s.parse().ok()).unwrap_or(1);
                return Err(ExecError::Continue(n));
            }
            "read" => return Ok(self.do_read(&args)),
            "local" => return Ok(self.do_local(&args)),
            "set" => return Ok(self.do_set(&args)),
            "shift" => return Ok(0),
            "eval" => {
                if args.is_empty() { return Ok(0); }
                let script = args.join(" ");
                return Ok(self.run_string(&script));
            }
            "exec" => return self.do_exec(&args, &cmd.redirects),
            "wait" => return Ok(self.do_wait(&args)),
            "kill" => return Ok(self.do_kill(&args)),
            "jobs" => {
                self.with_redirects(&cmd.redirects, || { self.print_jobs_fn(); 0 })?;
                return Ok(0);
            }
            "fg" => { eprintln!("nsh: no jobs to run"); return Ok(1); }
            "bg" => { eprintln!("nsh: no jobs to run"); return Ok(1); }
            "[" => {
                // strip trailing ]
                if args.last().map(|s| s.as_str()) == Some("]") { args.pop(); }
                return Ok(builtins::evaluate_test(&args));
            }
            "test" => return Ok(builtins::evaluate_test(&args)),
            _ => {}
        }

        // External command
        let env_overrides: Vec<(String, String)> = cmd.assigns.iter()
            .map(|(k, v)| (k.clone(), self.expand_word_to_str(v)))
            .collect();

        self.exec_external(&name, &args, &env_overrides, &cmd.redirects)
    }

    fn call_function(&mut self, name: &str, body: &CompoundList, 
                     args: &[String], redirects: &[Redirect]) -> Result<i32, ExecError> {
        let body = body.clone();
        self.frames.push(Frame { vars: HashMap::new(), locals: HashSet::new() });
        let result = match self.exec_list(&body) {
            Ok(rc) => Ok(rc),
            Err(ExecError::Return(rc)) => Ok(rc),
            Err(e) => Err(e),
        };
        self.frames.pop();
        result
    }

    fn exec_external(&mut self, name: &str, args: &[String], 
                     env: &[(String, String)], redirects: &[Redirect]) -> Result<i32, ExecError> {
        let prog = if name.contains('/') {
            name.to_string()
        } else {
            match find_in_path(name) {
                Some(p) => p,
                None => {
                    eprintln!("nsh: command not found `{}'", name);
                    self.last_exit = 1;
                    return Ok(1);
                }
            }
        };

        let pid = unsafe { sys::fork() };
        if pid < 0 { eprintln!("nsh: fork failed"); return Ok(1); }

        if pid == 0 {
            // Child
            apply_redirects(redirects);
            for (k, v) in env { std::env::set_var(k, v); }

            let prog_c = CString::new(prog.as_str()).unwrap();
            let mut argv: Vec<CString> = vec![CString::new(name).unwrap()];
            for a in args { argv.push(CString::new(a.as_str()).unwrap()); }
            let mut argv_ptrs: Vec<*const i8> = argv.iter().map(|s| s.as_ptr()).collect();
            argv_ptrs.push(std::ptr::null());

            unsafe { sys::execv(prog_c.as_ptr(), argv_ptrs.as_ptr()); }

            let errno = sys::get_errno();
            if errno == 13 /* EACCES */ {
                eprintln!("nsh: Failed to exec {:?} (EACCESS). chmod(1) may help.", name);
            } else {
                eprintln!("nsh: {}: exec failed ({})", name, errno);
            }
            std::process::exit(127);
        }

        let mut status = 0;
        unsafe { sys::waitpid(pid, &mut status, 0); }
        self.check_done_jobs();

        let rc = if WIFEXITED(status) { WEXITSTATUS(status) }
                 else if WIFSIGNALED(status) { 128 + WTERMSIG(status) }
                 else { 1 };
        self.last_exit = rc;
        Ok(rc)
    }

    fn check_done_jobs(&mut self) {
        let mut i = 0;
        while i < self.jobs.len() {
            let (pid, ref cmd) = self.jobs[i];
            let mut status = 0;
            let r = unsafe { sys::waitpid(pid, &mut status, sys::WNOHANG) };
            if r > 0 && WIFEXITED(status) {
                let cmd = cmd.clone();
                eprintln!("[{}] Done: {}", i+1, cmd);
                self.jobs.remove(i);
            } else {
                i += 1;
            }
        }
    }

    fn print_jobs_fn(&self) {
        for (i, (pid, cmd)) in self.jobs.iter().enumerate() {
            println!("[{}] Running: {}", i+1, cmd);
        }
    }

    pub fn capture_output(&mut self, list: &CompoundList) -> String {
        let mut fds = [0i32; 2];
        unsafe { sys::pipe(fds.as_mut_ptr()); }
        let (rfd, wfd) = (fds[0], fds[1]);

        let pid = unsafe { sys::fork() };
        if pid == 0 {
            unsafe { sys::close(rfd); sys::dup2(wfd, 1); sys::close(wfd); }
            let rc = match self.exec_list(list) {
                Ok(rc) => rc,
                Err(ExecError::Exit(rc)) => rc,
                Err(_) => 1,
            };
            std::process::exit(rc);
        }

        unsafe { sys::close(wfd); }

        let mut out = Vec::new();
        let mut buf = [0u8; 4096];
        loop {
            let n = unsafe { sys::read(rfd, buf.as_mut_ptr(), buf.len()) };
            if n <= 0 { break; }
            out.extend_from_slice(&buf[..n as usize]);
        }
        unsafe { sys::close(rfd); }
        let mut status = 0;
        unsafe { sys::waitpid(pid, &mut status, 0); }

        String::from_utf8_lossy(&out).to_string()
    }

    pub fn start_proc_sub(&mut self, list: &CompoundList) -> String {
        let mut fds = [0i32; 2];
        unsafe { sys::pipe(fds.as_mut_ptr()); }
        let (rfd, wfd) = (fds[0], fds[1]);

        let pid = unsafe { sys::fork() };
        if pid == 0 {
            unsafe { sys::close(rfd); sys::dup2(wfd, 1); sys::close(wfd); }
            let _ = self.exec_list(list);
            std::process::exit(0);
        }
        unsafe { sys::close(wfd); }
        format!("/dev/fd/{}", rfd)
    }

    pub fn eval_arith(&mut self, expr: &ArithExpr) -> i64 {
        match expr {
            ArithExpr::Num(n) => *n,
            ArithExpr::Var(name) => {
                self.get_var(name).unwrap_or_default().parse().unwrap_or(0)
            }
            ArithExpr::Add(a, b) => self.eval_arith(a) + self.eval_arith(b),
            ArithExpr::Sub(a, b) => self.eval_arith(a) - self.eval_arith(b),
            ArithExpr::Mul(a, b) => self.eval_arith(a) * self.eval_arith(b),
            ArithExpr::Div(a, b) => { let bv = self.eval_arith(b); if bv == 0 { 0 } else { self.eval_arith(a) / bv } }
            ArithExpr::Mod(a, b) => { let bv = self.eval_arith(b); if bv == 0 { 0 } else { self.eval_arith(a) % bv } }
            ArithExpr::Eq(a, b) => if self.eval_arith(a) == self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Ne(a, b) => if self.eval_arith(a) != self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Lt(a, b) => if self.eval_arith(a) < self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Le(a, b) => if self.eval_arith(a) <= self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Gt(a, b) => if self.eval_arith(a) > self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Ge(a, b) => if self.eval_arith(a) >= self.eval_arith(b) { 1 } else { 0 },
            ArithExpr::Neg(a) => -self.eval_arith(a),
            ArithExpr::PostInc(name) => {
                let v: i64 = self.get_var(name).unwrap_or_default().parse().unwrap_or(0);
                let nv = v + 1;
                self.set_var(name, &nv.to_string());
                nv // nsh bug: returns new value not old
            }
            ArithExpr::PostDec(name) => {
                let v: i64 = self.get_var(name).unwrap_or_default().parse().unwrap_or(0);
                let nv = v - 1;
                self.set_var(name, &nv.to_string());
                nv
            }
            ArithExpr::CmdSub(list) => {
                let out = self.capture_output(list);
                let s: String = out.chars().filter(|c| !c.is_whitespace()).collect();
                s.parse().unwrap_or(0)
            }
        }
    }

    pub fn eval_cond(&mut self, expr: &CondExpr) -> i32 {
        match expr {
            CondExpr::Word(w) => {
                let s = self.expand_word_to_str(w);
                if s.is_empty() { 1 } else { 0 }
            }
            CondExpr::BinOp { left, op, right } => {
                let l = self.expand_word_to_str(left);
                let r = self.expand_word_to_str(right);
                let ok = match op {
                    CondOp::Eq => l == r,
                    CondOp::Ne => l != r,
                    CondOp::Lt => l < r,
                    CondOp::Le => l <= r,
                    CondOp::Gt => l > r,
                    CondOp::Ge => l >= r,
                    CondOp::NumEq => l.parse::<i64>().unwrap_or(0) == r.parse::<i64>().unwrap_or(0),
                    CondOp::NumNe => l.parse::<i64>().unwrap_or(0) != r.parse::<i64>().unwrap_or(0),
                    CondOp::NumLt => l.parse::<i64>().unwrap_or(0) < r.parse::<i64>().unwrap_or(0),
                    CondOp::NumLe => l.parse::<i64>().unwrap_or(0) <= r.parse::<i64>().unwrap_or(0),
                    CondOp::NumGt => l.parse::<i64>().unwrap_or(0) > r.parse::<i64>().unwrap_or(0),
                    CondOp::NumGe => l.parse::<i64>().unwrap_or(0) >= r.parse::<i64>().unwrap_or(0),
                };
                if ok { 0 } else { 1 }
            }
            CondExpr::FileTest { flag, word } => {
                let val = self.expand_word_to_str(word);
                builtins::evaluate_test(&[format!("-{}", flag), val])
            }
            CondExpr::Not(e) => { let r = self.eval_cond(e); if r == 0 { 1 } else { 0 } }
            CondExpr::And(a, b) => { if self.eval_cond(a) == 0 { self.eval_cond(b) } else { 1 } }
            CondExpr::Or(a, b) => { if self.eval_cond(a) == 0 { 0 } else { self.eval_cond(b) } }
        }
    }

    pub fn expand_word_to_str(&mut self, word: &Word) -> String {
        expand::expand_to_string(word, self)
    }

    pub fn expand_word(&mut self, word: &Word) -> Vec<String> {
        expand::expand_to_words(word, self)
    }

    fn with_redirects<F: FnOnce() -> i32>(&mut self, redirects: &[Redirect], f: F) -> Result<i32, ExecError> {
        if redirects.is_empty() { return Ok(f()); }

        // Save fds
        let saved_out = unsafe { sys::dup(1) };
        let saved_err = unsafe { sys::dup(2) };
        let saved_in = unsafe { sys::dup(0) };

        apply_redirects(redirects);
        let rc = f();

        // Restore
        unsafe { sys::dup2(saved_out, 1); sys::close(saved_out); }
        unsafe { sys::dup2(saved_err, 2); sys::close(saved_err); }
        unsafe { sys::dup2(saved_in, 0); sys::close(saved_in); }

        let _ = std::io::stdout().flush();
        Ok(rc)
    }

    fn do_cd(&mut self, args: &[String]) -> i32 {
        let dir = if args.is_empty() {
            self.get_var("HOME").unwrap_or_else(|| "/".to_string())
        } else {
            args[0].clone()
        };
        match std::env::set_current_dir(&dir) {
            Ok(_) => {
                if let Ok(p) = std::env::current_dir() {
                    let pwd = p.to_string_lossy().to_string();
                    self.set_var("PWD", &pwd);
                    std::env::set_var("PWD", &pwd);
                }
                0
            }
            Err(e) => { eprintln!("nsh: cd: {}: {}", dir, e); 1 }
        }
    }

    fn do_export(&mut self, args: &[String]) -> i32 {
        for arg in args {
            if let Some(pos) = arg.find('=') {
                let k = &arg[..pos];
                let v = &arg[pos+1..];
                self.set_var(k, v);
                self.exported.insert(k.to_string());
                std::env::set_var(k, v);
            } else {
                self.exported.insert(arg.clone());
                if let Some(v) = self.get_var(arg) {
                    std::env::set_var(arg, &v);
                }
            }
        }
        0
    }

    fn do_alias(&self, args: &[String]) -> i32 {
        if args.is_empty() {
            let mut list: Vec<(&String, &String)> = self.aliases.iter().collect();
            list.sort_by_key(|(k, _)| k.as_str());
            for (k, v) in list { println!("{}='{}'", k, v); }
            return 0;
        }
        for arg in args {
            if let Some(pos) = arg.find('=') {
                // This needs &mut self but we have &self... 
                // We'll handle this differently
            } else {
                if let Some(v) = self.aliases.get(arg) {
                    println!("{}='{}'", arg, v);
                }
            }
        }
        0
    }

    pub fn do_alias_mut(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            let mut list: Vec<(String, String)> = self.aliases.iter()
                .map(|(k, v)| (k.clone(), v.clone())).collect();
            list.sort_by_key(|(k, _)| k.clone());
            for (k, v) in list { println!("{}='{}'", k, v); }
            return 0;
        }
        for arg in args {
            if let Some(pos) = arg.find('=') {
                let k = arg[..pos].to_string();
                let v = arg[pos+1..].to_string();
                // Strip surrounding quotes from value
                let v = if (v.starts_with('"') && v.ends_with('"')) || 
                           (v.starts_with('\'') && v.ends_with('\'')) {
                    v[1..v.len()-1].to_string()
                } else { v };
                self.aliases.insert(k, v);
            } else {
                if let Some(v) = self.aliases.get(arg) {
                    let v = v.clone();
                    println!("{}='{}'", arg, v);
                }
            }
        }
        0
    }

    fn do_read(&mut self, args: &[String]) -> i32 {
        let mut line = String::new();
        match io::stdin().read_line(&mut line) {
            Ok(0) => return 1,
            Ok(_) => {}
            Err(_) => return 1,
        }
        let line = line.trim_end_matches('\n').trim_end_matches('\r').to_string();
        if args.is_empty() {
            self.set_var("REPLY", &line);
        } else {
            let ifs = self.get_var("IFS").unwrap_or_else(|| " \t\n".to_string());
            let fields = expand::split_on_ifs(&line, &ifs);
            for (i, var) in args.iter().enumerate() {
                if i == args.len() - 1 {
                    let rest = fields.get(i..).map(|s| s.join(" ")).unwrap_or_default();
                    self.set_var(var, &rest);
                } else {
                    self.set_var(var, fields.get(i).map(|s| s.as_str()).unwrap_or(""));
                }
            }
        }
        0
    }

    fn do_local(&mut self, args: &[String]) -> i32 {
        for arg in args {
            if let Some(pos) = arg.find('=') {
                let k = &arg[..pos];
                let v = &arg[pos+1..];
                self.declare_local(k, Some(v));
            } else {
                self.declare_local(arg, None);
            }
        }
        0
    }

    fn do_set(&mut self, args: &[String]) -> i32 {
        if args.is_empty() { return 0; }
        if args[0] == "--help" || args[0] == "-h" {
            eprintln!("nsh: set: set 0.4.2\nSet command.\n\nUSAGE:\n    set [FLAGS]\n\nFLAGS:\n    -e               \n    -h, --help       Prints help information\n    -n               \n    -u               \n    -V, --version    Prints version information");
            return 1;
        }
        if args[0] == "--version" || args[0] == "-V" {
            eprintln!("nsh: set: set 0.4.2");
            return 1;
        }
        for arg in args {
            match arg.as_str() {
                "-e" => self.set_e = true,
                "+e" => self.set_e = false,
                "-n" => self.set_n = true,
                "+n" => self.set_n = false,
                "-u" => self.set_u = true,
                "+u" => self.set_u = false,
                s => {
                    eprintln!("nsh: set: error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    set [FLAGS]\n\nFor more information try --help", s);
                    return 1;
                }
            }
        }
        0
    }

    fn do_exec(&mut self, args: &[String], redirects: &[Redirect]) -> Result<i32, ExecError> {
        if args.is_empty() { return Ok(0); }
        let name = &args[0];
        let prog = if name.contains('/') { name.clone() }
            else { match find_in_path(name) { Some(p) => p, None => { eprintln!("nsh: {}: not found", name); return Ok(127); } } };

        apply_redirects(redirects);

        let prog_c = CString::new(prog.as_str()).unwrap();
        let mut argv: Vec<CString> = args.iter().map(|s| CString::new(s.as_str()).unwrap()).collect();
        let mut ptrs: Vec<*const i8> = argv.iter().map(|s| s.as_ptr()).collect();
        ptrs.push(std::ptr::null());
        unsafe { sys::execv(prog_c.as_ptr(), ptrs.as_ptr()); }
        Err(ExecError::Exit(1))
    }

    fn do_wait(&mut self, args: &[String]) -> i32 {
        if args.is_empty() {
            let mut status = 0;
            loop {
                let p = unsafe { sys::wait(&mut status) };
                if p <= 0 { break; }
            }
            self.jobs.clear();
        }
        0
    }

    fn do_kill(&mut self, args: &[String]) -> i32 {
        if args.is_empty() { return 1; }
        if args[0] == "-l" { builtins::builtin_kill_l(); return 0; }
        let (sig, pids) = if args[0].starts_with('-') {
            let s = parse_signal(&args[0][1..]);
            (s, &args[1..])
        } else { (15 /* SIGTERM */, args.as_slice()) };
        for p in pids {
            if let Ok(pid) = p.parse::<i32>() {
                unsafe { sys::kill(pid, sig); }
            }
        }
        0
    }

    pub fn run_interactive(&mut self) {
        use std::io::BufRead;
        let stdin = std::io::stdin();

        loop {
            let is_tty = unsafe { sys::isatty(0) } == 1;
            if is_tty {
                let prompt = self.global_vars.get("PROMPT")
                    .cloned()
                    .unwrap_or_else(|| "$ ".to_string());
                // Simple prompt rendering
                print!("{}", render_prompt(&prompt, self));
                let _ = std::io::stdout().flush();
            }

            let mut line = String::new();
            match stdin.lock().read_line(&mut line) {
                Ok(0) => break,
                Ok(_) => {}
                Err(_) => break,
            }

            let trimmed = line.trim_end_matches('\n').trim_end_matches('\r');
            if trimmed.is_empty() { continue; }

            // Save to history
            self.save_history(trimmed);

            match self.run_string(trimmed) {
                rc => { self.last_exit = rc; }
            }
        }
    }

    fn save_history(&self, cmd: &str) {
        use std::io::Write;
        if let Ok(home) = std::env::var("HOME") {
            let path = format!("{}/.nsh_history", home);
            if let Ok(mut f) = std::fs::OpenOptions::new().append(true).create(true).open(&path) {
                let time = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|d| d.as_secs())
                    .unwrap_or(0);
                let cwd = std::env::current_dir().map(|p| p.to_string_lossy().to_string())
                    .unwrap_or_default();
                let _ = writeln!(f, "{}\t{}\t{}", time, cwd, cmd);
            }
        }
    }
}

fn render_prompt(prompt: &str, shell: &Shell) -> String {
    // Simple prompt rendering - just return the string for now
    // The actual nsh prompt has \{var} syntax
    let mut result = String::new();
    let chars: Vec<char> = prompt.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\\' && i+1 < chars.len() {
            if chars[i+1] == '{' {
                let end = chars[i+2..].iter().position(|&c| c == '}').map(|p| i+2+p);
                if let Some(end) = end {
                    let name: String = chars[i+2..end].iter().collect();
                    match name.as_str() {
                        "reset" => result.push_str("\x1b[0m"),
                        "bold" => result.push_str("\x1b[1m"),
                        "red" => result.push_str("\x1b[31m"),
                        "green" => result.push_str("\x1b[32m"),
                        "yellow" => result.push_str("\x1b[33m"),
                        "blue" => result.push_str("\x1b[34m"),
                        "magenta" => result.push_str("\x1b[35m"),
                        "cyan" => result.push_str("\x1b[36m"),
                        "username" => {
                            let user = std::env::var("USER").unwrap_or_else(|_| "user".to_string());
                            result.push_str(&user);
                        }
                        "hostname" => {
                            let host = hostname();
                            result.push_str(&host);
                        }
                        "current_dir" => {
                            let cwd = std::env::current_dir()
                                .map(|p| p.to_string_lossy().to_string())
                                .unwrap_or_default();
                            // Shorten home dir
                            if let Some(home) = shell.get_var("HOME") {
                                if cwd.starts_with(&home) {
                                    result.push('~');
                                    result.push_str(&cwd[home.len()..]);
                                } else {
                                    result.push_str(&cwd);
                                }
                            } else {
                                result.push_str(&cwd);
                            }
                        }
                        "repo_status" => {
                            // Git status
                            result.push_str("master");
                        }
                        _ => {}
                    }
                    i = end + 1;
                    continue;
                }
            } else if chars[i+1] == 'n' {
                result.push('\n');
                i += 2;
                continue;
            } else if chars[i+1] == 'i' {
                // \if{cond}{then}{else}
                i += 2;
                continue;
            }
        }
        result.push(chars[i]);
        i += 1;
    }
    result
}

fn hostname() -> String {
    let mut buf = [0i8; 256];
    extern "C" { fn gethostname(name: *mut i8, len: usize) -> i32; }
    unsafe { gethostname(buf.as_mut_ptr(), buf.len()); }
    let len = buf.iter().position(|&c| c == 0).unwrap_or(buf.len());
    let bytes: Vec<u8> = buf[..len].iter().map(|&c| c as u8).collect();
    String::from_utf8_lossy(&bytes).to_string()
}

fn apply_redirects(redirects: &[Redirect]) {
    for r in redirects {
        match r {
            Redirect::Out(word) => {
                let path = word_literal(word);
                if let Ok(fd) = open_write(&path) {
                    unsafe { sys::dup2(fd, 1); sys::close(fd); }
                }
            }
            Redirect::Append(word) => {
                let path = word_literal(word);
                if let Ok(fd) = open_append(&path) {
                    unsafe { sys::dup2(fd, 1); sys::close(fd); }
                }
            }
            Redirect::In(word) => {
                let path = word_literal(word);
                if let Ok(fd) = open_read(&path) {
                    unsafe { sys::dup2(fd, 0); sys::close(fd); }
                }
            }
            Redirect::StderrOut(word) => {
                let path = word_literal(word);
                if let Ok(fd) = open_write(&path) {
                    unsafe { sys::dup2(fd, 2); sys::close(fd); }
                }
            }
            Redirect::StderrAppend(word) => {
                let path = word_literal(word);
                if let Ok(fd) = open_append(&path) {
                    unsafe { sys::dup2(fd, 2); sys::close(fd); }
                }
            }
            Redirect::StderrToStdout => { unsafe { sys::dup2(1, 2); } }
            Redirect::StdoutToStderr => { unsafe { sys::dup2(2, 1); } }
            Redirect::BothOut(word) => {
                let path = word_literal(word);
                if let Ok(fd) = open_write(&path) {
                    unsafe { sys::dup2(fd, 1); sys::dup2(fd, 2); sys::close(fd); }
                }
            }
            Redirect::FdOut(n, word) => {
                let path = word_literal(word);
                if let Ok(fd) = open_write(&path) {
                    unsafe { sys::dup2(fd, *n as i32); sys::close(fd); }
                }
            }
            Redirect::FdIn(n, word) => {
                let path = word_literal(word);
                if let Ok(fd) = open_read(&path) {
                    unsafe { sys::dup2(fd, *n as i32); sys::close(fd); }
                }
            }
            Redirect::FdDup(from, to) => {
                if *to == 999 {
                    unsafe { sys::close(*from as i32); }
                } else {
                    unsafe { sys::dup2(*to as i32, *from as i32); }
                }
            }
            Redirect::Heredoc { contents, .. } => {
                let mut fds = [0i32; 2];
                unsafe { sys::pipe(fds.as_mut_ptr()); }
                let bytes = contents.as_bytes();
                unsafe { sys::write(fds[1], bytes.as_ptr(), bytes.len()); sys::close(fds[1]); }
                unsafe { sys::dup2(fds[0], 0); sys::close(fds[0]); }
            }
            Redirect::ProcSubIn(_) => {} // Handled elsewhere
        }
    }
}

fn word_literal(word: &Word) -> String {
    word.parts.iter().filter_map(|p| if let WordPart::Literal(s) = p { Some(s.as_str()) } else { None })
        .collect::<Vec<_>>().join("")
}

fn open_write(path: &str) -> Result<i32, ()> {
    let c = CString::new(path).map_err(|_| ())?;
    let fd = unsafe { sys::open(c.as_ptr(), sys::O_WRONLY | sys::O_CREAT | sys::O_TRUNC, 0o644) };
    if fd < 0 { Err(()) } else { Ok(fd) }
}

fn open_append(path: &str) -> Result<i32, ()> {
    let c = CString::new(path).map_err(|_| ())?;
    let fd = unsafe { sys::open(c.as_ptr(), sys::O_WRONLY | sys::O_CREAT | sys::O_APPEND, 0o644) };
    if fd < 0 { Err(()) } else { Ok(fd) }
}

fn open_read(path: &str) -> Result<i32, ()> {
    let c = CString::new(path).map_err(|_| ())?;
    let fd = unsafe { sys::open(c.as_ptr(), sys::O_RDONLY, 0) };
    if fd < 0 { Err(()) } else { Ok(fd) }
}

fn find_in_path(name: &str) -> Option<String> {
    let path = std::env::var("PATH").unwrap_or_else(|_| "/usr/bin:/bin".to_string());
    for dir in path.split(':') {
        let full = format!("{}/{}", dir, name);
        if std::path::Path::new(&full).is_file() {
            use std::os::unix::fs::PermissionsExt;
            if let Ok(m) = std::fs::metadata(&full) {
                if m.permissions().mode() & 0o111 != 0 { return Some(full); }
            }
        }
    }
    None
}

fn parse_signal(s: &str) -> i32 {
    match s { "HUP"|"1"=>1, "INT"|"2"=>2, "QUIT"|"3"=>3, "KILL"|"9"=>9, "TERM"|"15"=>15,
              "STOP"|"19"=>19, "CONT"|"18"=>18, n => n.parse().unwrap_or(15) }
}
