# Wait, skip_ws is called before consume_keyword("do")
# Let me check: after the for-arith parser, we have:
#   self.skip_ws();
#   if !self.consume_keyword("do") ...
# But skip_ws skips spaces/tabs/newlines, not ;
# The ';' is not consumed!

