                let output = exec.capture_output(list);
                // In unquoted arg context, strip trailing newlines then split on IFS
                let trimmed = output.trim_end_matches('\\n');
                let ifs = exec.get_var("IFS").unwrap_or_else(|| " \\t\\n".to_string());
                let fields = split_on_ifs(trimmed, &ifs);
                if fields.is_empty() {
                    // Empty output - mark chunk as empty (will be filtered)
                } else if fields.len() == 1 {
                    let last = chunks.last_mut().unwrap();
                    last.push_str(&fields[0]);
                } else {
                    let last = chunks.last_mut().unwrap();
                    last.push_str(&fields[0]);
                    for f in &fields[1..] {
                        chunks.push(f.clone());
                    }
                }
            }'''

