# Fix call_function to pass args
old = '''    fn call_function(&mut self, name: &str, body: &CompoundList, 
                     args: &[String], redirects: &[Redirect]) -> Result<i32, ExecError> {
        let body = body.clone();
        self.frames.push(Frame { vars: HashMap::new(), locals: HashSet::new() });
        let result = match self.exec_list(&body) {
            Ok(rc) => Ok(rc),
            Err(ExecError::Return(rc)) => Ok(rc),
            Err(e) => Err(e),
        };
        self.frames.pop();
        result
    }'''

new = '''    fn call_function(&mut self, name: &str, body: &CompoundList, 
                     args: &[String], redirects: &[Redirect]) -> Result<i32, ExecError> {
        let body = body.clone();
        let mut frame = Frame { vars: HashMap::new(), locals: HashSet::new() };
        // Set positional parameters
        frame.vars.insert("#".to_string(), args.len().to_string());
        frame.vars.insert("@".to_string(), args.join(" "));
        frame.vars.insert("*".to_string(), args.join(" "));
        for (i, arg) in args.iter().enumerate() {
            frame.vars.insert((i+1).to_string(), arg.clone());
        }
        self.frames.push(frame);
        let result = match self.exec_list(&body) {
            Ok(rc) => Ok(rc),
            Err(ExecError::Return(rc)) => Ok(rc),
            Err(e) => Err(e),
        };
        self.frames.pop();
        result
    }'''

