# When elif is true, it runs the then body regardless of the if condition!
# But when elif is false (and else exists), it runs the else body.
# 
# The pattern: when the LAST CONDITION evaluated is 0 (success), run the THEN body.
# 
# This is the || bug applied to elif!
# In the original nsh, exec_if has this logic:
# 1. rc = exec_list(cond)
# 2. For each elif:
#    rc = exec_list(elif_cond)  <- OVERWRITES rc with elif result!
# 3. if rc == 0: run then_body
# 4. else if else_body exists: run else_body
# 
# This is BECAUSE in the original code, the elif conditions are evaluated
# sequentially, and the LAST one's result determines whether to run the then body!

# Let me replicate this behavior:
python3 << 'PYEOF'
with open('/workspace/nsh_impl/src/exec.rs', 'r') as f:
    content = f.read()

old = '''    fn exec_if(&mut self, cond: &CompoundList, then_b: &CompoundList, 
               elif_parts: &[(CompoundList, CompoundList)],
               else_b: &Option<CompoundList>) -> Result<i32, ExecError> {
        let rc = self.exec_list(cond)?;
        eprintln!("DEBUG exec_if: cond_rc={}", rc);
        if rc == 0 { return self.exec_list(then_b); }
        for (ec, eb) in elif_parts {
            let elif_rc = self.exec_list(ec)?;
            eprintln!("DEBUG exec_if: elif_rc={}", elif_rc);
            if elif_rc == 0 { return self.exec_list(eb); }
        }
        if let Some(e) = else_b { return self.exec_list(e); }
        Ok(0)
    }'''

